// Enemy stat multiplier per wave (index 0 = wave 1).
export const WAVE_SCALE = [0.82, 0.9, 1.0, 1.12, 1.2, 1.32, 1.44, 1.55];

export const WAVE_REWARDS = [10, 11, 12, 16, 14, 15, 16, 24];

export function waveData(wave) {
  if (wave <= WAVES.length) {
    return { ...WAVES[wave - 1], index: wave, scale: WAVE_SCALE[wave - 1], reward: WAVE_REWARDS[wave - 1] ?? 12 };
  }
  // Endless waves: generated from the boss template with rising scale.
  const n = wave - WAVES.length;
  const pool = ['wolf', 'bear', 'falcon', 'serpent', 'scorpion', 'toad', 'rhino', 'lynx', 'drake', 'golem', 'wraith', 'mantis'];
  const enemies = [];
  const count = Math.min(8, 5 + Math.floor(n / 2));
  for (let i = 0; i < count; i++) {
    const primary = pool[(wave * 3 + i * 5) % pool.length];
    const secondary = pool[(wave * 7 + i * 3 + 2) % pool.length];
    enemies.push({
      species: primary,
      secondary: i % 2 === 0 ? secondary : undefined,
      tier: Math.min(4, 2 + Math.floor((n + i) / 3)),
      lane: (i * 3 + wave) % 5,
      row: i % 2 === 0 ? 'front' : 'back',
    });
  }
  return {
    name: `Endless Rite ${n}`,
    subtitle: 'The gate hungers still',
    desc: 'The arena resets, but the beasts grow stranger.',
    enemies,
    scale: 1.55 + n * 0.12,
    reward: 18,
    index: wave,
    heroic: true,
  };
}

export const STARTING_ROSTER = ['wolf', 'bear', 'falcon', 'serpent'];
export const START_ESSENCE = 14;
export const SPLICE_BASE_COST = 4;
export const SHOP_REROLL_COST = 2;

import { SPECIES, TIER_NAMES, TRAITS } from './data.js';

let nextId = 1;
export function newId() { return `u${nextId++}`; }
export function resetIds() { nextId = 1; }

// ── colour helpers ───────────────────────────────────────────────────────────
function hexToRgb(hex) {
  const h = hex.replace('#', '');
  return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
}
export function mix(a, b, t = 0.5) {
  const A = hexToRgb(a); const B = hexToRgb(b);
  return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0')).join('');
}
export function shade(hex, amt) {
  const c = hexToRgb(hex);
  return '#' + c.map((v) => Math.max(0, Math.min(255, Math.round(v + amt))).toString(16).padStart(2, '0')).join('');
}

// ── art descriptor ──────────────────────────────────────────────────────────
export function buildArt(primaryKey, secondaryKey, tier = 1) {
  const A = SPECIES[primaryKey];
  const B = secondaryKey ? SPECIES[secondaryKey] : null;
  const p = A.palette;
  const q = B ? B.palette : A.palette;
  const feats = new Set(A.features);
  if (B) for (const f of B.features) feats.add(f);
  return {
    body: A.body,
    accentBody: B ? B.body : null,
    primary: primaryKey,
    secondary: secondaryKey || null,
    c1: mix(p.c1, q.c1, B ? 0.32 : 0),
    c2: mix(p.c2, q.c2, B ? 0.32 : 0),
    belly: mix(p.belly, q.belly, B ? 0.4 : 0),
    glow: B ? q.glow : p.glow,
    eyeL: p.eye,
    eyeR: B ? q.eye : p.eye,
    feats,
    tier,
    scale: 1 + (tier - 1) * 0.055 + (feats.has('bulk') ? 0.07 : 0),
  };
}

export function fullName(primaryKey, secondaryKey, tier) {
  const A = SPECIES[primaryKey];
  const B = secondaryKey ? SPECIES[secondaryKey] : A;
  const base = A.prefix + B.suffix;
  return tier > 1 ? `${TIER_NAMES[tier] || ''} ${base}` : base;
}

export function speciesLine(unit) {
  if (!unit.secondary) return SPECIES[unit.primary].name;
  return `${SPECIES[unit.primary].name} / ${SPECIES[unit.secondary].name}`;
}

export function abilityOf(unit) { return SPECIES[unit.primary].ability; }

// ── unit factories ──────────────────────────────────────────────────────────
export function makeBaseUnit(primaryKey, opts = {}) {
  const S = SPECIES[primaryKey];
  const tier = opts.tier || 1;
  const secondary = opts.secondary || null;
  const stats = {
    hp: Math.round(S.stats.hp * (tier > 1 ? [1, 1.55, 2.15, 2.85][tier] : 1)),
    atk: Math.round(S.stats.atk * (tier > 1 ? [1, 1.55, 2.15, 2.85][tier] : 1)),
    interval: S.stats.interval,
    range: S.stats.range,
    speed: S.stats.speed,
  };
  return {
    id: opts.id || newId(),
    name: opts.name || fullName(primaryKey, secondary, tier),
    primary: primaryKey,
    secondary,
    tier,
    role: S.role,
    stats,
    traits: pickTraits([S.traits, secondary ? SPECIES[secondary].traits : []], traitCap(tier)),
    ability: S.ability,
    art: buildArt(primaryKey, secondary, tier),
    enemy: !!opts.enemy,
    lore: S.blurb,
  };
}

export function scaleUnit(unit, mul) {
  unit.stats = {
    ...unit.stats,
    hp: Math.round(unit.stats.hp * mul),
    atk: Math.round(unit.stats.atk * mul),
  };
  return unit;
}

export function traitCap(tier) { return tier >= 3 ? 4 : tier === 2 ? 3 : 2; }

export function pickTraits(groups, cap) {
  const out = [];
  const maxLen = Math.max(...groups.map((g) => g.length), 0);
  for (let i = 0; i < maxLen && out.length < cap; i++) {
    for (const g of groups) {
      const t = g[i];
      if (t && !out.includes(t) && out.length < cap) out.push(t);
    }
  }
  return out;
}

// ── splice ──────────────────────────────────────────────────────────────────
export function spliceCost(a, b) {
  return 4 + a.tier + b.tier;
}

export function previewSplice(a, b) {
  const maxHp = Math.max(a.stats.hp, b.stats.hp);
  const minHp = Math.min(a.stats.hp, b.stats.hp);
  const maxAtk = Math.max(a.stats.atk, b.stats.atk);
  const minAtk = Math.min(a.stats.atk, b.stats.atk);
  const tier = Math.min(4, Math.max(a.tier, b.tier) + 1);
  const traits = pickTraits([a.traits, b.traits], traitCap(tier));
  const stats = {
    hp: Math.round(maxHp * 1.1 + minHp * 0.45 + 62 * tier),
    atk: Math.round(maxAtk * 1.1 + minAtk * 0.45 + 5 * tier),
    interval: Math.max(0.55, +(((a.stats.interval + b.stats.interval) / 2) * 0.94).toFixed(2)),
    range: a.stats.range,
    speed: Math.round((a.stats.speed + b.stats.speed) / 2),
  };
  return {
    id: newId(),
    name: fullName(a.primary, b.primary, tier),
    primary: a.primary,
    secondary: b.primary,
    tier,
    role: SPECIES[a.primary].role,
    stats,
    traits,
    ability: SPECIES[a.primary].ability,
    art: buildArt(a.primary, b.primary, tier),
    lore: `Spliced from ${a.name} and ${b.name}. ${SPECIES[a.primary].blurb}`,
    parents: [a.id, b.id],
  };
}

export function applySplice(roster, aId, bId) {
  const a = roster.find((u) => u.id === aId);
  const b = roster.find((u) => u.id === bId);
  if (!a || !b || a === b) return null;
  const hybrid = previewSplice(a, b);
  const rest = roster.filter((u) => u.id !== aId && u.id !== bId);
  return { hybrid, roster: [...rest, hybrid], cost: spliceCost(a, b) };
}

// ── display helpers ─────────────────────────────────────────────────────────
export function statTags(unit) {
  return {
    hp: unit.stats.hp,
    atk: unit.stats.atk,
    dps: Math.round((unit.stats.atk / unit.stats.interval) * 10) / 10,
    range: unit.stats.range >= 150 ? 'Ranged' : 'Melee',
  };
}

export function traitList(unit) {
  return unit.traits.map((t) => TRAITS[t]).filter(Boolean);
}

export function combatPower(unit) {
  const dps = (unit.stats.atk / unit.stats.interval) * (unit.stats.range >= 150 ? 0.9 : 1.05);
  return Math.round(unit.stats.hp * 0.42 + dps * 18 + unit.traits.length * 42 + unit.tier * 60);
}

export function uniqueName(name, roster) {
  if (!roster.some((u) => u.name === name)) return name;
  let i = 2;
  while (roster.some((u) => u.name === `${name} ${['', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII'][i] || i}`)) i++;
  return `${name} ${['', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII'][i] || i}`;
}

// ── CHIMERA FRONT · procedural creature illustration ────────────────────────
import { shade, mix } from './units.js';

const TAU = Math.PI * 2;
const DARK = '#0a0d13';

function E(ctx, x, y, rx, ry, rot = 0) {
  ctx.beginPath();
  ctx.ellipse(x, y, Math.max(0.1, rx), Math.max(0.1, ry), rot, 0, TAU);
}
function fill(ctx, color) { if (color) { ctx.fillStyle = color; ctx.fill(); } }
function stroke(ctx, color, w = 2.5) { if (color) { ctx.strokeStyle = color; ctx.lineWidth = w; ctx.stroke(); } }
function ell(ctx, x, y, rx, ry, color, rot = 0, line, lw = 2.5) {
  E(ctx, x, y, rx, ry, rot); fill(ctx, color); stroke(ctx, line, lw);
}
function circ(ctx, x, y, r, color, line, lw = 2.5) {
  ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); fill(ctx, color); stroke(ctx, line, lw);
}
function rrect(ctx, x, y, w, h, r, color, rot = 0, line, lw = 2.5) {
  ctx.save(); ctx.translate(x + w / 2, y + h / 2); if (rot) ctx.rotate(rot);
  ctx.beginPath(); ctx.roundRect(-w / 2, -h / 2, w, h, r); fill(ctx, color); stroke(ctx, line, lw); ctx.restore();
}
function tri(ctx, a, b, c, color, line, lw = 2.5) {
  ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.lineTo(c[0], c[1]); ctx.closePath();
  fill(ctx, color); stroke(ctx, line, lw);
}
function limb(ctx, pts, width, color, line, lw = 2) {
  ctx.beginPath(); ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.strokeStyle = line || color; ctx.lineWidth = width + (line ? lw * 2 : 0); ctx.stroke();
  ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
}
function grad(ctx, x0, y0, x1, y1, stops) {
  const g = ctx.createLinearGradient(x0, y0, x1, y1);
  stops.forEach(([p, c]) => g.addColorStop(p, c));
  return g;
}
function radial(ctx, x, y, r0, r1, stops) {
  const g = ctx.createRadialGradient(x, y, r0, x, y, r1);
  stops.forEach(([p, c]) => g.addColorStop(p, c));
  return g;
}

function eye(ctx, x, y, rx, ry, color, opts = {}) {
  const { rot = 0, slit = true, glow = true, pupil = DARK } = opts;
  ctx.save();
  E(ctx, x, y, rx * 1.35, ry * 1.35, rot); fill(ctx, 'rgba(4,7,12,.9)');
  if (glow) { ctx.shadowColor = color; ctx.shadowBlur = 9; }
  E(ctx, x, y, rx, ry, rot); fill(ctx, color);
  ctx.shadowBlur = 0;
  if (slit) {
    E(ctx, x + rx * 0.1, y, Math.max(0.8, rx * 0.24), ry * 0.8, rot); fill(ctx, pupil);
  } else {
    circ(ctx, x, y, Math.max(1, rx * 0.32), pupil);
  }
  ctx.restore();
}

function claws(ctx, x, y, dir, color, size = 1) {
  ctx.save(); ctx.translate(x, y); ctx.scale(size, size);
  for (let i = 0; i < 3; i++) {
    const ox = (i - 1) * 4.3;
    ctx.beginPath();
    ctx.moveTo(ox, 0); ctx.quadraticCurveTo(ox + 1, 4 * dir, ox + 3 * dir, 7 * dir);
    ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.lineCap = 'round'; ctx.stroke();
  }
  ctx.restore();
}

function teeth(ctx, x, y, color) {
  for (let i = -1; i <= 1; i++) {
    tri(ctx, [x + i * 4 - 1.8, y], [x + i * 4 + 1.8, y], [x + i * 4, y + 4.4], color, null);
  }
}

// ══ BODY ARCHETYPES ═════════════════════════════════════════════════════════

function drawBeast(ctx, a, o) {
  const { c1, c2, belly, glow, feats } = a;
  const bulk = feats.has('bulk') || a.primary === 'bear' || a.primary === 'rhino';
  const wolfish = a.primary === 'wolf' || a.primary === 'lynx' || feats.has('mane');
  const outline = shade(c2, -18);
  const bw = bulk ? 33 : 26;
  const bh = bulk ? 33 : 30;

  // tail
  if (feats.has('tail')) {
    ctx.save();
    const sway = Math.sin(o.time * 2 + o.seed) * 3;
    ctx.beginPath();
    ctx.moveTo(16, -40);
    ctx.bezierCurveTo(38, -36 + sway, 43, -18, 35, -6 + sway);
    ctx.strokeStyle = outline; ctx.lineWidth = 13; ctx.lineCap = 'round'; ctx.stroke();
    ctx.strokeStyle = c1; ctx.lineWidth = 9; ctx.stroke();
    if (wolfish) { E(ctx, 34, -5 + sway, 6, 8, 0.5); fill(ctx, belly); }
    ctx.restore();
  }

  // rear legs
  ell(ctx, -bw * 0.55, -15, bulk ? 13 : 10, 16, c2, 0, outline);
  ell(ctx, bw * 0.55, -15, bulk ? 13 : 10, 16, c2, 0, outline);
  ell(ctx, -bw * 0.58, -3, 11, 5, shade(c2, 14), 0, outline, 2);
  ell(ctx, bw * 0.58, -3, 11, 5, shade(c2, 14), 0, outline, 2);

  // body
  E(ctx, 0, -46, bw, bh);
  fill(ctx, grad(ctx, -bw, -82, bw, -12, [[0, shade(c1, 26)], [0.55, c1], [1, shade(c2, 6)]]));
  stroke(ctx, outline, 3);
  // belly
  E(ctx, 0, -37, bw * 0.58, bh * 0.56);
  fill(ctx, mix(belly, c1, 0.22));
  // shoulder shading
  E(ctx, -bw * 0.72, -58, 12, 16, 'rgba(255,255,255,.07)', -0.2);
  E(ctx, bw * 0.72, -58, 12, 16, 'rgba(0,0,0,.12)', 0.2);

  // mane collar
  if (feats.has('mane') || a.primary === 'wolf') {
    ctx.beginPath();
    for (let i = 0; i <= 10; i++) {
      const ang = Math.PI * 0.05 + (i / 10) * Math.PI * 0.9;
      const r = i % 2 ? 30 : 23;
      const x = Math.cos(ang) * r;
      const y = -72 + Math.sin(ang) * r * 0.72;
      i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    }
    ctx.lineTo(-bw * 0.9, -50); ctx.lineTo(bw * 0.9, -50); ctx.closePath();
    fill(ctx, shade(c2, 4));
  }

  // arms
  const armX = bulk ? 33 : 27;
  limb(ctx, [[-armX, -55], [-armX - 4, -34], [-armX - 2, -18]], bulk ? 14 : 10, c1, outline);
  limb(ctx, [[armX, -55], [armX + 4, -34], [armX + 2, -18]], bulk ? 14 : 10, c1, outline);
  circ(ctx, -armX - 2, -16, bulk ? 8 : 6, shade(c1, -4), outline);
  circ(ctx, armX + 2, -16, bulk ? 8 : 6, shade(c1, -4), outline);
  if (feats.has('claws') || bulk) {
    claws(ctx, -armX - 4, -12, 1, '#e8e2d4', bulk ? 1.2 : 0.9);
    claws(ctx, armX + 4, -12, 1, '#e8e2d4', bulk ? 1.2 : 0.9);
  }

  // head
  const hx = 0, hy = -83;
  const hr = bulk ? 23 : 20;
  ell(ctx, hx, hy, hr, hr * 0.95, grad(ctx, -hr, hy - hr, hr, hy + hr, [[0, shade(c1, 32)], [1, c1]]), 0, outline, 3);

  // ears
  if (feats.has('tuftEars')) {
    tri(ctx, [-17, hy - 12], [-25, hy - 33], [-7, hy - 21], c1, outline);
    tri(ctx, [17, hy - 12], [25, hy - 33], [7, hy - 21], c1, outline);
    E(ctx, -21, hy - 29, 2.6, 6, belly, -0.4); E(ctx, 21, hy - 29, 2.6, 6, belly, 0.4);
  } else if (feats.has('ears')) {
    tri(ctx, [-15, hy - 10], [-20, hy - 31], [-4, hy - 20], c1, outline);
    tri(ctx, [15, hy - 10], [20, hy - 31], [4, hy - 20], c1, outline);
    tri(ctx, [-13, hy - 13], [-16, hy - 26], [-7, hy - 19], shade(belly, -14), null);
    tri(ctx, [13, hy - 13], [16, hy - 26], [7, hy - 19], shade(belly, -14), null);
  }

  // muzzle
  ell(ctx, 0, hy + 9, bulk ? 14 : 11, bulk ? 10 : 8.5, shade(belly, -3), 0, outline, 2);
  ell(ctx, 0, hy + 6.5, 4.2, 3, DARK);
  // mouth / fangs
  if (bulk || wolfish) {
    ctx.beginPath(); ctx.moveTo(-7, hy + 14); ctx.quadraticCurveTo(0, hy + 17, 7, hy + 14);
    ctx.strokeStyle = outline; ctx.lineWidth = 1.6; ctx.stroke();
    if (bulk) {
      tri(ctx, [-10, hy + 12], [-6, hy + 18], [-4, hy + 12], '#f0e6cf', null);
      tri(ctx, [10, hy + 12], [6, hy + 18], [4, hy + 12], '#f0e6cf', null);
    }
  }
  // eyes
  eye(ctx, -7.5, hy - 3, 3.4, 3.2, a.eyeL, { rot: -0.15 });
  eye(ctx, 7.5, hy - 3, 3.4, 3.2, a.eyeR, { rot: 0.15 });
  // brow
  ctx.beginPath(); ctx.moveTo(-13, hy - 8); ctx.lineTo(-4, hy - 6); ctx.moveTo(13, hy - 8); ctx.lineTo(4, hy - 6);
  ctx.strokeStyle = shade(c2, -8); ctx.lineWidth = 2; ctx.stroke();

  // rhino horn
  if (feats.has('horn') || a.primary === 'rhino') {
    const hg = grad(ctx, 0, -100, 0, -135, [[0, '#f6dca4'], [1, '#a8794b']]);
    ctx.beginPath(); ctx.moveTo(-5, hy + 1); ctx.quadraticCurveTo(-3, hy - 26, 2, hy - 37);
    ctx.quadraticCurveTo(8, hy - 20, 7, hy + 2); ctx.closePath(); fill(ctx, hg); stroke(ctx, outline, 2);
    ctx.beginPath(); ctx.moveTo(-2, hy - 2); ctx.quadraticCurveTo(0, hy - 22, 2, hy - 31);
    ctx.strokeStyle = 'rgba(255,255,255,.4)'; ctx.lineWidth = 2; ctx.stroke();
  }
  if (feats.has('tusks') && !feats.has('horn')) {
    tri(ctx, [-12, hy + 11], [-16, hy + 22], [-8, hy + 14], '#efe3cd', outline, 1.2);
    tri(ctx, [12, hy + 11], [16, hy + 22], [8, hy + 14], '#efe3cd', outline, 1.2);
  }

  // patterns
  if (feats.has('spots')) {
    ctx.save(); E(ctx, 0, -46, bw - 1, bh - 1); ctx.clip();
    for (let i = 0; i < 7; i++) {
      const x = ((i * 37) % 48) - 24; const y = -30 - ((i * 23) % 44);
      E(ctx, x, y, 3.5, 2.6, 0.3); fill(ctx, shade(c2, 8));
    }
    ctx.restore();
  }
  if (feats.has('plates') && !feats.has('horn')) {
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.moveTo(-bw + 6, -58 + i * 10); ctx.quadraticCurveTo(0, -64 + i * 10, bw - 6, -58 + i * 10);
      ctx.strokeStyle = shade(c2, -2); ctx.lineWidth = 4; ctx.stroke();
