    ctx.quadraticCurveTo(-8, hy - 18, 0, hy - 22);
    ctx.quadraticCurveTo(8, hy - 18, 30, hy - 26);
    ctx.quadraticCurveTo(40, hy - 4, 0, hy + 12);
    fill(ctx, grad(ctx, -30, hy - 20, 30, hy + 10, [[0, shade(c1, 10)], [1, c2]]));
