    ctx.strokeStyle = 'rgba(255,255,255,.18)'; ctx.lineWidth = 2; ctx.stroke();
  }

  // head
  ell(ctx, 0, hy, 12, 15, grad(ctx, -12, hy - 15, 12, hy + 15, [[0, shade(c1, 22)], [1, c1]]), 0, outline, 2.5);
