  // fangs
  tri(ctx, [-4.5, hy + 13], [-3, hy + 21], [-1.4, hy + 13], '#f2ead5', outline, 1);
  tri(ctx, [4.5, hy + 13], [3, hy + 21], [1.4, hy + 13], '#f2ead5', outline, 1);
  // eyes
  eye(ctx, -6.5, hy - 4, 3.1, 2.4, a.eyeL, { rot: -0.25 });
