    ctx.beginPath();
    ctx.moveTo(-4, -30);
    ctx.bezierCurveTo(-44, -46, -50, -84, -18, -98);
    ctx.strokeStyle = outline; ctx.lineWidth = 12; ctx.lineCap = 'round'; ctx.stroke();
    ctx.strokeStyle = c1; ctx.lineWidth = 8; ctx.stroke();
    for (let i = 0; i < 4; i++) {
      const t = i / 4;
