  if (feats.has('plates') && !scorp) {
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.arc(0, -40 - i * 9, 13 + i, 0.2, Math.PI - 0.2);
      ctx.strokeStyle = shade(belly, -30); ctx.lineWidth = 2; ctx.stroke();
