    const lift = (s === -1 ? flap : -flap) * 0.6;
    ctx.beginPath();
    ctx.moveTo(s * 12, -62);
    ctx.quadraticCurveTo(s * 46, -96 - lift, s * 58, -54 - lift);
    ctx.quadraticCurveTo(s * 42, -58, s * 38, -40);
