      ctx.strokeStyle = shade(c2, 12); ctx.lineWidth = 2; ctx.stroke();
    }
  }

  // legs
  ell(ctx, -18, -16, 10, 15, c2, 0, outline, 2);
  ell(ctx, 18, -16, 10, 15, c2, 0, outline, 2);
  ell(ctx, -19, -3, 12, 4.5, shade(c2, 16), 0, outline, 1.6);
  ell(ctx, 19, -3, 12, 4.5, shade(c2, 16), 0, outline, 1.6);
  claws(ctx, -22, -2, 1, '#f0e2c0', 0.9); claws(ctx, 22, -2, 1, '#f0e2c0', 0.9);

