  ctx.save(); ctx.shadowColor = glow; ctx.shadowBlur = 9;
  circ(ctx, -4, hy + 8, 1.3, glow); circ(ctx, 4, hy + 8, 1.3, glow);
  ctx.restore();

  // dorsal spikes
  if (feats.has('spikes')) {
    for (let i = 0; i < 4; i++) {
      tri(ctx, [-4, -52 - i * 7], [0, -60 - i * 7], [4, -52 - i * 7], c2, outline, 1);
    }
  }
  if (feats.has('runes')) {
    ctx.save(); ctx.shadowColor = glow; ctx.shadowBlur = 9; ctx.strokeStyle = glow; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(-8, -50); ctx.lineTo(0, -44); ctx.lineTo(8, -50); ctx.stroke();
    ctx.restore();
  }
}

function drawConstruct(ctx, a, o) {
  const { c1, c2, belly, glow, feats } = a;
  const outline = shade(c2, -24);
  const float = Math.sin(o.time * 1.6 + o.seed) * 1.2;

  // legs / base
  rrect(ctx, -24, -22, 17, 24, 5, shade(c2, 6), 0, outline, 2.4);
  rrect(ctx, 7, -22, 17, 24, 5, shade(c2, 6), 0, outline, 2.4);
  ell(ctx, -16, -2, 15, 5, shade(c2, 16), 0, outline, 1.6);
  ell(ctx, 16, -2, 15, 5, shade(c2, 16), 0, outline, 1.6);

  // floating shoulder stones
  for (const s of [-1, 1]) {
    E(ctx, s * 40, -63 + (s === 1 ? float : -float), 9, 12, -0.3 * s);
    fill(ctx, grad(ctx, s * 32, -78, s * 48, -48, [[0, shade(c1, 14)], [1, c2]]));
    stroke(ctx, outline, 2);
  }

  // arms
  for (const s of [-1, 1]) {
    rrect(ctx, s * 30 - 8, -58, 16, 32, 7, c1, 0.08 * s, outline, 2.2);
    E(ctx, s * 34, -28, 11, 10, 0); fill(ctx, shade(c1, -4)); stroke(ctx, outline, 2);
    for (let i = 0; i < 3; i++) {
      rrect(ctx, s * 34 - 8 + i * 6, -24, 5, 11, 2.5, shade(c2, 16), 0, outline, 1.2);
    }
  }

  // torso block
  ctx.beginPath();
  ctx.moveTo(-26, -58); ctx.lineTo(-21, -86); ctx.lineTo(-10, -94); ctx.lineTo(12, -93);
  ctx.lineTo(23, -84); ctx.lineTo(27, -54); ctx.lineTo(20, -22); ctx.lineTo(-22, -23); ctx.closePath();
  fill(ctx, grad(ctx, -26, -92, 26, -22, [[0, shade(c1, 22)], [0.55, c1], [1, c2]]));
  stroke(ctx, outline, 3);
  // cracks
  ctx.beginPath(); ctx.moveTo(-14, -84); ctx.lineTo(-7, -68); ctx.lineTo(-12, -55); ctx.lineTo(-3, -36);
  ctx.strokeStyle = shade(c2, -12); ctx.lineWidth = 2; ctx.stroke();

  // rune core
  ctx.save();
  ctx.shadowColor = glow; ctx.shadowBlur = 18;
  E(ctx, 0, -52, 10, 12); fill(ctx, 'rgba(8,20,24,.8)'); stroke(ctx, glow, 2);
  ctx.shadowBlur = 10;
  ctx.beginPath(); ctx.moveTo(0, -62); ctx.lineTo(5, -52); ctx.lineTo(0, -42); ctx.lineTo(-5, -52); ctx.closePath();
  ctx.fillStyle = glow; ctx.fill();
  ctx.restore();

  // shoulder plates
  rrect(ctx, -22, -80, 15, 14, 5, shade(c1, 8), 0.35, outline, 1.8);
  rrect(ctx, 7, -80, 15, 14, 5, shade(c1, 4), -0.35, outline, 1.8);

  // head
  const hy = -100;
  ctx.beginPath();
  ctx.moveTo(-13, hy + 12); ctx.lineTo(-16, hy - 7); ctx.lineTo(-6, hy - 16); ctx.lineTo(7, hy - 16);
  ctx.lineTo(16, hy - 6); ctx.lineTo(13, hy + 12); ctx.closePath();
  fill(ctx, grad(ctx, -15, hy - 16, 15, hy + 12, [[0, shade(c1, 18)], [1, c1]]));
  stroke(ctx, outline, 2.4);
  // eyes
  ctx.save(); ctx.shadowColor = glow; ctx.shadowBlur = 10;
  rrect(ctx, -9, hy - 5, 6, 3.4, 1.5, glow, 0, null);
  rrect(ctx, 3, hy - 5, 6, 3.4, 1.5, a.eyeR, 0, null);
  ctx.restore();
  // head crystal
  tri(ctx, [-4, hy - 15], [0, hy - 28], [4, hy - 15], glow, outline, 1.2);

  if (feats.has('horn')) {
    tri(ctx, [-15, hy - 4], [-30, hy - 20], [-9, hy - 12], '#d8c6a2', outline, 1.4);
    tri(ctx, [15, hy - 4], [30, hy - 20], [9, hy - 12], '#d8c6a2', outline, 1.4);
  }
  if (feats.has('plates')) {
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.moveTo(-24, -40 - i * 8); ctx.lineTo(24, -45 - i * 8);
      ctx.strokeStyle = 'rgba(255,255,255,.07)'; ctx.lineWidth = 2; ctx.stroke();
    }
  }
  if (feats.has('mane')) {
    for (let i = 0; i < 5; i++) {
      tri(ctx, [-20 + i * 10, -82], [-13 + i * 10, -92], [-8 + i * 10, -80], c2, outline, 1);
    }
  }
}

function drawSpirit(ctx, a, o) {
  const { c1, c2, belly, glow, feats } = a;
  const outline = shade(c2, -24);
  const float = Math.sin(o.time * 2 + o.seed) * 3;

  // tattered cloak
  ctx.beginPath();
  ctx.moveTo(-26, -64);
  ctx.quadraticCurveTo(-38, -36, -30, -6);
  for (let i = 0; i < 5; i++) {
    const x = -30 + i * 14;
    ctx.lineTo(x + 5, -1 + ((i % 2) * 9) + float * 0.3);
    ctx.lineTo(x + 10, -10 + (i % 2) * 4);
  }
  ctx.quadraticCurveTo(36, -34, 26, -66);
  ctx.closePath();
  fill(ctx, grad(ctx, 0, -70, 0, -2, [[0, c1], [0.65, c2], [1, 'rgba(10,12,20,.75)']]));
  stroke(ctx, outline, 2.6);

  // inner glow at hem
  ctx.save(); ctx.shadowColor = glow; ctx.shadowBlur = 16;
  ctx.beginPath(); ctx.moveTo(-18, -74); ctx.quadraticCurveTo(0, -40, 18, -74);
  ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 10; ctx.stroke();
  ctx.restore();

  // tattered wings
  if (feats.has('wings')) {
    for (const s of [-1, 1]) {
      ctx.beginPath(); ctx.moveTo(s * 18, -62);
      ctx.quadraticCurveTo(s * 54, -74, s * 46, -32);
      ctx.lineTo(s * 38, -40); ctx.lineTo(s * 34, -26); ctx.lineTo(s * 26, -36);
      ctx.closePath();
      fill(ctx, 'rgba(170,140,255,.14)'); stroke(ctx, 'rgba(190,165,255,.28)', 1.2);
    }
  }

  // arms / claws
  for (const s of [-1, 1]) {
    limb(ctx, [[s * 20, -60], [s * 34, -44], [s * 32, -30]], 7, shade(c1, 4), outline, 1.4);
    claws(ctx, s * 32, -28, 1, '#e8dcff', 0.9);
    ctx.beginPath(); ctx.moveTo(s * 30, -32); ctx.quadraticCurveTo(s * 40, -26, s * 34, -20);
    ctx.strokeStyle = 'rgba(200,180,255,.35)'; ctx.lineWidth = 3; ctx.stroke();
  }

  // hood
  const hy = -83;
  ctx.beginPath();
  ctx.moveTo(-19, hy + 18); ctx.quadraticCurveTo(-26, hy - 10, 0, hy - 24);
  ctx.quadraticCurveTo(26, hy - 10, 19, hy + 18);
  ctx.quadraticCurveTo(9, hy + 8, 0, hy + 9);
  ctx.quadraticCurveTo(-9, hy + 8, -19, hy + 18);
  fill(ctx, grad(ctx, -20, hy - 20, 20, hy + 16, [[0, shade(c1, 14)], [1, c2]]));
  stroke(ctx, outline, 2.4);
  // hood opening
  E(ctx, 0, hy + 2, 11, 12); fill(ctx, '#0a0714');
  // eyes
  ctx.save(); ctx.shadowColor = a.glow; ctx.shadowBlur = 12;
  E(ctx, -5, hy, 2.6, 3.4, -0.15); fill(ctx, a.eyeL);
  E(ctx, 5, hy, 2.6, 3.4, 0.15); fill(ctx, a.eyeR);
  ctx.restore();
  // tiny wisps
  ctx.save(); ctx.globalAlpha = 0.5;
  for (let i = 0; i < 4; i++) {
    const ang = o.time * 1.1 + i * 1.7;
    E(ctx, Math.cos(ang) * (26 + i * 3), -50 + Math.sin(ang * 1.4) * 20, 1.5, 2.6, ang);
    fill(ctx, glow);
  }
  ctx.restore();
}

const BODIES = {
  beast: drawBeast,
  bird: drawBird,
  serpent: drawSerpent,
  insect: drawInsect,
  amphibian: drawAmphibian,
  dragon: drawDragon,
  construct: drawConstruct,
  spirit: drawSpirit,
};

// ── cross-lineage ornaments ────────────────────────────────────────────────
function drawWingsBack(ctx, a, o) {
  if (a.accentBody === 'bird' || a.body === 'bird' || a.body === 'dragon' || a.body === 'spirit') return;
  if (!a.feats.has('wings')) return;
  const flap = Math.sin(o.time * 2 + o.seed) * 4;
  for (const s of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(s * 14, -64);
    ctx.quadraticCurveTo(s * 56, -92 - flap, s * 62, -46 - flap);
    ctx.quadraticCurveTo(s * 42, -50, s * 34, -34);
    ctx.quadraticCurveTo(s * 26, -46, s * 14, -40);
    ctx.closePath();
    fill(ctx, 'rgba(160,220,255,.10)');
    stroke(ctx, 'rgba(190,235,255,.22)', 1.2);
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.moveTo(s * 16, -58);
      ctx.quadraticCurveTo(s * 38, -68 - i * 6, s * 54 - i * 4, -48 + i * 3);
      ctx.strokeStyle = 'rgba(255,255,255,.12)'; ctx.lineWidth = 1; ctx.stroke();
    }
  }
}

function drawExtraTail(ctx, a, o) {
  if (['beast', 'serpent', 'dragon', 'insect', 'spirit'].includes(a.body)) return;
  if (!a.feats.has('tail') && !a.feats.has('stinger')) return;
  ctx.beginPath(); ctx.moveTo(16, -40);
  ctx.bezierCurveTo(44, -34, 50, -12, 34, 0);
  ctx.strokeStyle = shade(a.c2, -20); ctx.lineWidth = 10; ctx.lineCap = 'round'; ctx.stroke();
  ctx.strokeStyle = a.c1; ctx.lineWidth = 6; ctx.stroke();
  if (a.feats.has('stinger')) {
    ctx.save(); ctx.shadowColor = a.glow; ctx.shadowBlur = 8;
    tri(ctx, [30, -4], [42, 0], [33, 7], a.glow, shade(a.c2, -20), 1);
    ctx.restore();
  }
}

function drawExtraHorns(ctx, a) {
  if (a.feats.has('horn') === false) return;
  if (!['insect', 'bird', 'amphibian', 'serpent', 'spirit'].includes(a.body)) return;
  const hy = a.body === 'amphibian' ? -58 : a.body === 'insect' ? -90 : -80;
  tri(ctx, [-10, hy], [-20, hy - 22], [-3, hy - 8], '#e8d3a4', shade(a.c2, -18), 1.2);
  tri(ctx, [10, hy], [20, hy - 22], [3, hy - 8], '#e8d3a4', shade(a.c2, -18), 1.2);
}

function drawTierHalo(ctx, a, o) {
  if (a.tier < 3) return;
  ctx.save();
  ctx.globalAlpha = 0.5;
  for (let i = 0; i < 3; i++) {
    const ang = o.time * 0.9 + i * TAU / 3;
    const x = Math.cos(ang) * 34;
    const y = -92 + Math.sin(ang) * 8;
    ctx.save(); ctx.translate(x, y); ctx.rotate(ang + Math.PI / 2);
    ctx.beginPath(); ctx.moveTo(0, -3); ctx.lineTo(2.4, 0); ctx.lineTo(0, 3); ctx.lineTo(-2.4, 0); ctx.closePath();
    ctx.fillStyle = a.glow; ctx.shadowColor = a.glow; ctx.shadowBlur = 8; ctx.fill();
    ctx.restore();
  }
  ctx.restore();
}

// ══ PUBLIC DRAW ═════════════════════════════════════════════════════════════
export function drawCreature(ctx, art, x, y, scale, opts = {}) {
  const {
    time = 0, seed = 0, alpha = 1, team = 'player', flash = 0,
    animate = true, ring = true, dead = false, bob = 1,
  } = opts;
  ctx.save();
  ctx.translate(x, y);
  ctx.globalAlpha = alpha;
  if (dead) ctx.globalAlpha *= 0.5;

  // team aura + ground ring
  if (ring) {
    const teamColor = team === 'player' ? '#5fe3d1' : '#ff5c6c';
    ctx.save();
    ctx.translate(0, 2);
    ctx.scale(1, 0.3);
    const g = ctx.createRadialGradient(0, 0, 2, 0, 0, 42 * scale);
    g.addColorStop(0, `${teamColor}66`); g.addColorStop(1, `${teamColor}00`);
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0, 0, 42 * scale, 0, TAU); ctx.fill();
    ctx.strokeStyle = `${teamColor}88`; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.arc(0, 0, 28 * scale, 0, TAU); ctx.stroke();
    ctx.restore();
  }

  // shadow
  ctx.save(); ctx.scale(1, 0.34);
  const sh = ctx.createRadialGradient(0, 0, 2, 0, 0, 30);
  sh.addColorStop(0, 'rgba(0,0,0,.55)'); sh.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = sh; ctx.beginPath(); ctx.arc(0, 4, 30, 0, TAU); ctx.fill();
  ctx.restore();

  if (animate && bob) ctx.translate(0, Math.sin(time * 2.2 + seed) * 1.4);
  ctx.scale(scale, scale);
  if (flash > 0.01) ctx.filter = `brightness(${1 + flash * 1.9}) saturate(${1 + flash})`;

  const a = art;
  drawWingsBack(ctx, a, { ...opts, time, seed });
  drawExtraTail(ctx, a, { time, seed });
  const draw = BODIES[a.body] || drawBeast;
  draw(ctx, a, { time, seed, team });
  drawExtraHorns(ctx, a);
  if (a.tier >= 3) drawTierHalo(ctx, a, { time });

  ctx.restore();
}

export function drawPortrait(canvas, unit, size = 96, opts = {}) {
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  canvas.width = size * dpr; canvas.height = size * dpr;
  canvas.style.width = size + 'px'; canvas.style.height = size + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  const scale = (size / 132) * 1.02 * (unit.art.scale || 1);
  drawCreature(ctx, unit.art, size / 2, size * 0.94, scale, {
    ring: false, animate: false, time: 0, seed: 0, ...opts,
  });
}

// ── CHIMERA FRONT · deterministic-ish lane battle simulation ────────────────
import { NEXUS_HP, waveData } from './data.js';
import { makeBaseUnit, scaleUnit } from './units.js';

export const WORLD = { w: 1000, h: 620 };
export const LANE_X = [100, 300, 500, 700, 900];
export const START_Y = {
  player: { front: 452, back: 560 },
  enemy: { front: 172, back: 68 },
};
export const NEXUS_Y = { player: 604, enemy: 16 };
export const FIELD_MIN = 40;
export const FIELD_MAX = 580;
const ABILITY_AUTO_DELAY = { player: 6, enemy: 1.4 };

const rnd = (a, b) => a + Math.random() * (b - a);

function makeCombatUnit(unit, side, lane, row, idx) {
  const traits = new Set(unit.traits);
  const maxHp = unit.stats.hp;
  return {
    ref: unit,
    name: unit.name,
    side, lane, row,
    x: LANE_X[lane] + (row === 'front' ? -14 : 14) * (side === 'player' ? 1 : -1),
    y: START_Y[side][row] + ((idx % 3) - 1) * 2,
    maxHp,
    hp: maxHp,
    shield: traits.has('aegis') ? Math.round(maxHp * 0.25) : 0,
    atk: unit.stats.atk,
    interval: unit.stats.interval,
    range: unit.stats.range,
    speed: unit.stats.speed,
    traits,
    ability: unit.ability,
    tier: unit.tier,
    energy: 0,
    energyMax: 100,
    autoCastAt: 0,
    attackTimer: rnd(0.05, 0.5),
    status: { slow: 0, slowUntil: 0, stunUntil: 0, atkBuff: 0, atkBuffUntil: 0, haste: 0, hasteUntil: 0 },
    poison: [],
    burn: null,
    dotTimer: 0,
    flash: 0,
    lunge: 0,
    hitAnim: 0,
    alive: true,
    deathT: 0,
    atNexus: false,
    breakAnnounced: false,
    casts: 0,
    dmgDone: 0,
    healDone: 0,
  };
}

export function createBattle({ roster, slots, wave }) {
  const wd = waveData(wave);
  const battle = {
    time: 0,
    duration: 60,
    wave,
    waveData: wd,
    units: [],
    playerNexus: NEXUS_HP,
    enemyNexus: NEXUS_HP,
    events: [],
    over: false,
    winner: null,
    bloodrush: false,
    shake: 0,
    slots,
    roster,
    startedAt: performance.now ? performance.now() : 0,
  };

  let idx = 0;
  for (const [key, unitId] of Object.entries(slots || {})) {
    if (!unitId) continue;
    const ru = roster.find((u) => u.id === unitId);
    if (!ru) continue;
    const [laneS, row] = key.split('-');
    const lane = Number(laneS);
    if (lane < 0 || lane > 4) continue;
    battle.units.push(makeCombatUnit(ru, 'player', lane, row, idx++));
  }

  (wd.enemies || []).forEach((e, i) => {
    const ru = makeBaseUnit(e.species, {
      secondary: e.secondary,
      tier: e.tier || 1,
      name: e.name,
      enemy: true,
    });
    scaleUnit(ru, wd.scale);
    // Bosses gain a little extra bite.
    if (e.name) scaleUnit(ru, 1.06);
    battle.units.push(makeCombatUnit(ru, 'enemy', e.lane, e.row, 100 + i));
  });

  return battle;
}

function ev(b, type, data = {}) {
  b.events.push({ type, t: b.time, ...data });
}

export function drainEvents(b) {
  const out = b.events;
  b.events = [];
  return out;
}

const alive = (u) => u.alive && u.hp > 0;
const enemiesOf = (b, side) => b.units.filter((u) => alive(u) && u.side !== side);
const alliesOf = (b, side) => b.units.filter((u) => alive(u) && u.side === side);

function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

function sym(b, u) {
  return u.side === 'player' ? b.enemyNexus : b.playerNexus;
}
function hurtNexus(b, u, amount) {
  if (u.side === 'player') b.enemyNexus = Math.max(0, b.enemyNexus - amount);
  else b.playerNexus = Math.max(0, b.playerNexus - amount);
  u.dmgDone += amount;
  b.shake = Math.max(b.shake, Math.min(14, 4 + amount * 0.25));
  ev(b, 'nexus', {
    side: u.side === 'player' ? 'enemy' : 'player',
    from: u.side, lane: u.lane,
    x: LANE_X[u.lane], y: u.side === 'player' ? NEXUS_Y.enemy : NEXUS_Y.player,
    amount: Math.round(amount),
  });
  if (b.enemyNexus <= 0 && !b.over) finish(b, 'player');
  else if (b.playerNexus <= 0 && !b.over) finish(b, 'enemy');
}

function finish(b, winner) {
  if (b.over) return;
  b.over = true;
  b.winner = winner;
  ev(b, 'end', { winner });
}

function healUnit(b, u, amount, silent = false) {
  if (!alive(u) || amount <= 0) return;
  const before = u.hp;
  u.hp = Math.min(u.maxHp, u.hp + amount);
  const healed = Math.round(u.hp - before);
  if (healed > 0) {
    u.healDone += healed;
    ev(b, 'heal', { x: u.x, y: u.y - 58, amount: healed, side: u.side });
  }
}

function addPoison(b, target, dps, dur) {
  target.poison = target.poison.filter((p) => p.until > b.time);
  target.poison.push({ dps, until: b.time + dur });
  if (target.poison.length > 3) target.poison.shift();
}

function directDamage(b, src, tgt, raw, kind = 'melee', opts = {}) {
  if (!alive(tgt) || raw <= 0) return 0;
  if (tgt.traits.has('phase') && Math.random() < 0.15) {
    ev(b, 'dodge', { x: tgt.x, y: tgt.y - 52, side: tgt.side });
    return 0;
  }
  let dmg = raw;
  if (tgt.traits.has('guard')) dmg *= 0.82;
  if (src && src.traits.has('execute') && tgt.hp / tgt.maxHp < 0.35) dmg *= 1.5;
  if (kind === 'ability' && opts.ignoreGuard) dmg = raw;

  // shield first
  if (tgt.shield > 0) {
    const absorbed = Math.min(tgt.shield, dmg);
    tgt.shield -= absorbed;
    dmg -= absorbed;
    ev(b, 'shieldHit', { x: tgt.x, y: tgt.y - 52, amount: Math.round(absorbed) });
  }
  const rounded = Math.max(1, Math.round(dmg));
  tgt.hp -= rounded;
  tgt.flash = 1;
  tgt.hitAnim = 1;
  tgt.energy = Math.min(tgt.energyMax, tgt.energy + Math.max(3, rounded * 0.12));
  tgt.dotTimer = 0;
  if (src) {
    src.dmgDone += rounded;
    if (src.traits.has('leech')) {
      const healed = Math.round(rounded * 0.22);
      src.hp = Math.min(src.maxHp, src.hp + healed);
      src.healDone += healed;
    }
  }
  ev(b, 'hit', {
    x: tgt.x + rnd(-6, 6), y: tgt.y - 50 + rnd(-8, 8),
    amount: rounded, kind,
    crit: !!(src && src.traits.has('execute') && tgt.hp / tgt.maxHp < 0.35),
    side: tgt.side,
  });
  if (kind === 'melee' && tgt.traits.has('thorns') && src && alive(src)) {
    const reflect = Math.max(1, Math.round(raw * 0.2));
    src.hp -= reflect;
    src.flash = 0.7;
    ev(b, 'thorns', { x: src.x, y: src.y - 48, amount: reflect });
    if (src.hp <= 0) killUnit(b, src);
  }
  if (tgt.hp <= 0) killUnit(b, tgt);
  return rounded;
}

function killUnit(b, u) {
  if (!u.alive) return;
  u.alive = false;
  u.deathT = 0;
  u.hp = 0;
  ev(b, 'death', { x: u.x, y: u.y - 35, side: u.side, lane: u.lane, name: u.name, color: u.ref.art.glow, tier: u.tier });
}

function aspdBonus(u) {
  let m = 1;
  if (u.traits.has('swift')) m *= 1.08;
  if (u.traits.has('frenzy') && u.hp / u.maxHp < 0.5) m *= 1.3;
  if (u.status.hasteUntil > 0) m *= 1 + u.status.haste;
  if (u.status.slowUntil > 0) m *= 1 - u.status.slow;
  return m;
}
function moveBonus(u) {
  let m = 1;
  if (u.traits.has('swift')) m *= 1.15;
  if (u.status.slowUntil > 0) m *= 1 - u.status.slow;
  return m;
}
function atkBonus(u) {
  return u.status.atkBuffUntil > 0 ? 1 + u.status.atkBuff : 1;
}

function acquireTarget(b, u) {
  const melee = u.range < 150;
  let best = null;
  let bestScore = Infinity;
  for (const e of b.units) {
    if (!alive(e) || e.side === u.side) continue;
    const laneDiff = Math.abs(e.lane - u.lane);
    if (melee && laneDiff !== 0) continue;
    if (!melee && laneDiff > 1) continue;
    const d = dist(u, e);
    const reach = u.range + (melee ? 16 : 12) + Math.abs(e.x - u.x) * 0;
    if (d > reach) continue;
    let score = d + laneDiff * 100;
    if (score < bestScore) { bestScore = score; best = e; }
  }
  return best;
}

function sameLaneEnemy(b, u) {
  return b.units.find((e) => alive(e) && e.side !== u.side && e.lane === u.lane) || null;
}

function nearestLaneEnemy(b, u) {
  let best = null; let bd = Infinity;
  for (const e of b.units) {
    if (!alive(e) || e.side === u.side) continue;
    const d = Math.abs(e.y - u.y) + Math.abs(e.lane - u.lane) * 60;
    if (d < bd) { bd = d; best = e; }
  }
  return best;
}

function allyAheadY(b, u) {
  let limit = u.side === 'player' ? -Infinity : Infinity;
  for (const a of b.units) {
    if (!alive(a) || a === u || a.side !== u.side || a.lane !== u.lane) continue;
    if (u.side === 'player' && a.y < u.y) limit = Math.max(limit, a.y + 42);
    if (u.side === 'enemy' && a.y > u.y) limit = Math.min(limit, a.y - 42);
  }
  return limit;
}

function moveUnit(b, u, dt, target, dir) {
  let step = u.speed * moveBonus(u) * dt;
  if (u.bloodrush) step *= 1.15;
  if (step <= 0) return;
  let ny = u.y + dir * step;

  // don't walk through the target
  if (target && Math.abs(target.lane - u.lane) === 0) {
    const stop = Math.min(u.range * 0.9, 96);
    if (dir < 0) ny = Math.max(ny, target.y + stop);
    else ny = Math.min(ny, target.y - stop);
  }
  // don't stack on allies
  const allyLimit = allyAheadY(b, u);
  if (dir < 0 && allyLimit > -Infinity) ny = Math.max(ny, allyLimit);
  if (dir > 0 && allyLimit < Infinity) ny = Math.min(ny, allyLimit);

  ny = Math.max(FIELD_MIN, Math.min(FIELD_MAX, ny));
  const mover = dir < 0 ? ny < u.y : ny > u.y;
  u.walking = mover;
  u.y = ny;
}

export function castAbility(b, u) {
  if (!alive(u) || u.energy < 100) return false;
  u.energy = 0;
  u.autoCastAt = 0;
  u.casts++;
  const skill = u.ref.ability;
  const hurt = directDamage;
  const foes = enemiesOf(b, u.side);
  const mates = alliesOf(b, u.side);
  const ownLaneFoes = foes.filter((f) => f.lane === u.lane);
  const adjacentFoes = foes.filter((f) => Math.abs(f.lane - u.lane) <= 1);
  const adjacentMates = mates.filter((m) => Math.abs(m.lane - u.lane) <= 1);
  const weakest = (list) => list.slice().sort((a, c) => a.hp / a.maxHp - c.hp / c.maxHp)[0];
  const closest = (list, maxD = 999) => list.filter((f) => dist(u, f) <= maxD).sort((a, c) => dist(u, a) - dist(u, c))[0];
  let kind = 'damage';
  let points = [];
  let targets = [];

  switch (skill) {
    case 'howl': {
      kind = 'buff';
      for (const m of mates) {
        m.status.atkBuff = Math.max(m.status.atkBuff, 0.28);
        m.status.atkBuffUntil = b.time + 6;
        points.push({ x: m.x, y: m.y - 60 });
      }
      healUnit(b, u, u.maxHp * 0.08);
      break;
    }
    case 'shockwave': {
      targets = ownLaneFoes;
      for (const f of targets) {
        hurt(b, u, f, u.atk * 1.6, 'ability');
        f.status.stunUntil = Math.max(f.status.stunUntil, b.time + 2.2);
        points.push({ x: f.x, y: f.y - 40 });
      }
      b.shake = Math.max(b.shake, 10);
      break;
    }
    case 'dive': {
      const t = weakest(adjacentFoes) || weakest(foes);
      if (t) {
        hurt(b, u, t, u.atk * 3.4, 'ability');
        t.status.slow = 0.4; t.status.slowUntil = b.time + 2.4;
        points.push({ x: t.x, y: t.y - 40 });
        targets = [t];
      }
      break;
    }
    case 'venomNova': {
      kind = 'debuff';
      targets = adjacentFoes;
      for (const f of targets) {
        hurt(b, u, f, u.atk * 0.7, 'ability');
        addPoison(b, f, 3 + u.atk * 0.18, 6);
        points.push({ x: f.x, y: f.y - 40 });
      }
      break;
    }
    case 'sting': {
      const t = weakest(adjacentFoes) || weakest(foes);
      if (t) {
        const missing = t.maxHp - t.hp;
        hurt(b, u, t, u.atk * 1.7 + missing * 0.22, 'ability');
        t.status.slow = 0.3; t.status.slowUntil = b.time + 2;
        points.push({ x: t.x, y: t.y - 40 });
        targets = [t];
      }
      break;
    }
    case 'mend': {
      kind = 'heal';
      const wounded = mates.slice().sort((a, c) => a.hp / a.maxHp - c.hp / c.maxHp).slice(0, 3);
      for (const m of wounded) {
        healUnit(b, m, m.maxHp * 0.24);
        points.push({ x: m.x, y: m.y - 55 });
      }
      break;
    }
    case 'gore': {
      targets = ownLaneFoes;
      for (const f of targets) {
        hurt(b, u, f, u.atk * 1.7, 'ability');
        f.status.stunUntil = Math.max(f.status.stunUntil, b.time + 1.6);
        f.y += u.side === 'player' ? 48 : -48;
        f.y = Math.max(FIELD_MIN, Math.min(FIELD_MAX, f.y));
        points.push({ x: f.x, y: f.y - 36 });
      }
      b.shake = Math.max(b.shake, 9);
      break;
    }
    case 'pounce': {
      const t = closest(adjacentFoes, 300) || weakest(foes);
      if (t) {
        hurt(b, u, t, u.atk * 2.5, 'ability');
        u.status.haste = 0.55; u.status.hasteUntil = b.time + 4;
        points.push({ x: t.x, y: t.y - 40 });
        targets = [t];
      }
      break;
    }
    case 'breath': {
      kind = 'cone';
      targets = adjacentFoes;
      for (const f of targets) {
        hurt(b, u, f, u.atk * 1.15, 'ability');
        f.burn = { dps: 4 + u.atk * 0.16, until: b.time + 4 };
        points.push({ x: f.x, y: f.y - 38 });
      }
      break;
    }
    case 'fortify': {
      kind = 'shield';
      for (const m of adjacentMates) {
        m.shield += Math.round(m.maxHp * 0.26);
        points.push({ x: m.x, y: m.y - 55 });
      }
      break;
    }
    case 'drain': {
      const t = closest(adjacentFoes, 320) || ownLaneFoes[0] || weakest(foes);
      if (t) {
        const dealt = hurt(b, u, t, u.atk * 2.0, 'ability');
        healUnit(b, u, dealt * 0.65 + u.maxHp * 0.08);
        points.push({ x: t.x, y: t.y - 40 });
        targets = [t];
      }
      break;
    }
    case 'reap': {
      const t = weakest(ownLaneFoes) || weakest(adjacentFoes);
      if (t) {
        for (let i = 0; i < 3; i++) hurt(b, u, t, u.atk * 0.95, 'ability');
        points.push({ x: t.x, y: t.y - 40 });
        targets = [t];
      }
      break;
    }
    default: break;
  }

  u.lunge = 1;
  b.shake = Math.max(b.shake, 4);
  ev(b, 'cast', {
    x: u.x, y: u.y - 56, lane: u.lane, side: u.side,
    ability: skill, kind, color: u.ref.art.glow,
    points: points.slice(0, 8),
  });
  return true;
}

function attack(b, u, target) {
  const melee = u.range < 150;
  const base = u.atk * atkBonus(u) * (u.bloodrush ? 1.3 : 1) * rnd(0.92, 1.08);
  const dmg = directDamage(b, u, target, base, melee ? 'melee' : 'ranged');
  u.lunge = 1;
  if (melee) {
    ev(b, 'slash', { x: u.x, y: u.y - 44, tx: target.x, ty: target.y - 44, side: u.side, color: u.ref.art.glow });
    if (u.traits.has('venom')) addPoison(b, target, 2.5 + u.atk * 0.12, 4);
    if (u.traits.has('frost')) { target.status.slow = Math.max(target.status.slow, 0.25); target.status.slowUntil = b.time + 1.6; }
    if (u.traits.has('burn')) target.burn = { dps: 3 + u.atk * 0.16, until: b.time + 3 };
  } else {
    ev(b, 'shot', {
      x: u.x, y: u.y - 48, tx: target.x, ty: target.y - 36, side: u.side,
      color: u.ref.art.glow, kind: u.ref.primary,
    });
    if (u.traits.has('venom')) addPoison(b, target, 2.5 + u.atk * 0.12, 4);
    if (u.traits.has('frost')) { target.status.slow = Math.max(target.status.slow, 0.25); target.status.slowUntil = b.time + 1.6; }
    if (u.traits.has('burn')) target.burn = { dps: 3 + u.atk * 0.16, until: b.time + 3 };
  }
  // flurry
  if (u.traits.has('flurry') && Math.random() < 0.22 && alive(target)) {
    directDamage(b, u, target, base * 0.62, melee ? 'melee' : 'ranged');
    ev(b, 'flurry', { x: u.x, y: u.y - 50, color: u.ref.art.glow });
  }
  u.energy = Math.min(u.energyMax, u.energy + 13);
}

function tickDots(b, u, dt) {
  if (u.poison.length) {
    u.poison = u.poison.filter((p) => p.until > b.time);
    if (u.poison.length) {
      const dps = u.poison.reduce((s, p) => s + p.dps, 0);
      const dmg = dps * dt;
      u.hp -= dmg;
      u.dotTimer += dt;
      if (u.dotTimer > 0.75) {
        u.dotTimer = 0;
        ev(b, 'dot', { x: u.x + 8, y: u.y - 46, amount: Math.max(1, Math.round(dmg + dps * 0.4)), color: '#b8ef6a' });
      }
    }
  }
  if (u.burn && u.burn.until > b.time) {
    const dmg = u.burn.dps * dt;
    u.hp -= dmg;
    u.dotTimer += dt;
    if (u.dotTimer > 0.85) {
      u.dotTimer = 0;
      ev(b, 'dot', { x: u.x - 8, y: u.y - 44, amount: Math.max(1, Math.round(dmg + u.burn.dps * 0.3)), color: '#ff9a5c' });
    }
  } else if (u.burn) u.burn = null;

  if (u.traits.has('regen') && u.hp < u.maxHp) {
    u.hp = Math.min(u.maxHp, u.hp + u.maxHp * 0.02 * dt);
  }
  if (u.hp <= 0) killUnit(b, u);
}

function updateUnit(b, u, dt) {
  if (!alive(u)) { u.deathT += dt; return; }
  if (u.status.stunUntil > b.time) {
    u.walking = false;
    u.flash = Math.max(0, u.flash - dt * 3);
    return;
  }
  if (u.status.slowUntil <= b.time) u.status.slow = 0;
  if (u.status.atkBuffUntil <= b.time) u.status.atkBuff = 0;
  if (u.status.hasteUntil <= b.time) u.status.haste = 0;

  u.flash = Math.max(0, u.flash - dt * 4.5);
  u.lunge = Math.max(0, u.lunge - dt * 6);
  u.hitAnim = Math.max(0, u.hitAnim - dt * 5);
  u.walking = false;

  tickDots(b, u, dt);
  if (!alive(u)) return;

  // energy + auto cast
  u.energy = Math.min(u.energyMax, u.energy + dt * 5.2);
  if (u.energy >= u.energyMax && u.autoCastAt === 0) {
    u.autoCastAt = b.time + (u.side === 'player' ? ABILITY_AUTO_DELAY.player : ABILITY_AUTO_DELAY.enemy * rnd(0.7, 1.4));
  }
  if (u.energy >= u.energyMax && u.autoCastAt > 0 && b.time >= u.autoCastAt) {
    castAbility(b, u);
  }

  const target = acquireTarget(b, u);
  const dir = u.side === 'player' ? -1 : 1;
  const inLaneFoe = sameLaneEnemy(b, u);

  // nexus attack?
  if (!inLaneFoe) {
    const canNexus = u.side === 'player' ? u.y <= 96 : u.y >= 524;
    if (canNexus) {
      if (!u.breakAnnounced) {
        u.breakAnnounced = true;
        u.atNexus = true;
        ev(b, 'laneBreak', { side: u.side, lane: u.lane, color: u.ref.art.glow });
      }
      u.attackTimer -= dt;
      if (u.attackTimer <= 0) {
        const amount = Math.max(7, u.atk * 0.55 * (u.bloodrush ? 1.4 : 1));
        hurtNexus(b, u, amount);
        u.attackTimer = u.interval / aspdBonus(u) * 1.05;
        ev(b, 'nexusStrike', { x: u.x, y: u.y - 40, side: u.side, color: u.ref.art.glow });
      }
      return;
    }
    if (target) {
      // ranged support from adjacent lane: hold position and fire
      if (u.range >= 150) {
        // shoot
      } else {
        // melee never has cross-lane target
      }
    }
  }

  if (target) {
    u.attackTimer -= dt;
    if (u.attackTimer <= 0) {
      attack(b, u, target);
      u.attackTimer = u.interval / aspdBonus(u);
    }
    // drift forward if target is far (mostly ranged lanes)
    if (dist(u, target) > u.range * 0.92) {
      moveUnit(b, u, dt, target, dir);
    }
  } else if (inLaneFoe) {
    // enemy exists in lane but is out of reach → advance
    moveUnit(b, u, dt, inLaneFoe, dir);
  } else {
    const any = nearestLaneEnemy(b, u);
    if (any) moveUnit(b, u, dt, null, dir);
    else moveUnit(b, u, dt, null, dir);
  }
}

export function stepBattle(b, dt) {
  if (b.over) return;
  dt = Math.min(dt, 0.05);
  b.time += dt;
  b.shake = Math.max(0, b.shake - dt * 22);

  if (!b.bloodrush && b.time >= 40) {
    b.bloodrush = true;
    for (const u of b.units) u.bloodrush = true;
    ev(b, 'bloodrush', {});
  }

  for (const u of b.units) updateUnit(b, u, dt);

  if (b.time >= b.duration && !b.over) {
    const p = b.playerNexus / NEXUS_HP;
    const e = b.enemyNexus / NEXUS_HP;
    if (p > e) finish(b, 'player');
    else if (e > p) finish(b, 'enemy');
    else {
      const pScore = b.units.filter((u) => u.side === 'player' && alive(u)).reduce((s, u) => s + u.hp / u.maxHp, 0);
      const eScore = b.units.filter((u) => u.side === 'enemy' && alive(u)).reduce((s, u) => s + u.hp / u.maxHp, 0);
      finish(b, pScore >= eScore ? 'player' : 'enemy');
    }
  }
}

export function readyUnits(b, side = 'player') {
  return b.units.filter((u) => u.side === side && alive(u) && u.energy >= 100);
}

export function autoCastIn(b, u) {
  if (!alive(u) || u.energy < 100) return null;
  if (!u.autoCastAt) return null;
  return Math.max(0, u.autoCastAt - b.time);
}

// ── CHIMERA FRONT · arena & title renderer ──────────────────────────────────
import { drawCreature } from './art.js';
import { LANE_X } from './battle.js';
import { drawCreature as drawC } from './art.js';

export const WORLD = { w: 1000, h: 620 };
const SLOT_Y = {
  player: { front: 424, back: 536 },
  enemy: { front: 220, back: 110 },
};
const GATE_Y = { player: 602, enemy: 18 };
const LANE_ROMAN = ['I', 'II', 'III', 'IV', 'V'];
const TEAM = { player: '#5fe3d1', enemy: '#ff5c6c' };

function rgba(hex, a) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function rnd(a, b) { return a + Math.random() * (b - a); }
function rr(ctx, x, y, w, h, r) {
  ctx.beginPath(); ctx.roundRect(x, y, w, h, r);
}
function diamond(ctx, x, y, r) {
  ctx.beginPath(); ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
}
function hexPath(ctx, x, y, r) {
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = Math.PI / 3 * i - Math.PI / 6;
    const px = x + Math.cos(a) * r; const py = y + Math.sin(a) * r;
    i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
  }
  ctx.closePath();
}

export class ArenaView {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.fx = [];
    this.floats = [];
    this.projectiles = [];
    this.time = 0;
    this.shake = 0;
    this.flashRed = 0;
    this.motes = Array.from({ length: 42 }, () => ({
      x: rnd(20, 980), y: rnd(30, 610), r: rnd(0.8, 2.4), sp: rnd(2, 9),
      ph: rnd(0, 6.28), hue: Math.random() < 0.3 ? '#ffcf8a' : '#8fe8ff',
    }));
    this.souls = [];
    this.view = { scale: 1, ox: 0, oy: 0, dpr: 1, w: 1000, h: 620 };
    this.pulse = 0;
    this.initRunes();
    this.resize();
  }

  initRunes() {
    this.runes = [
      { x: 500, y: 320, r: 150, rot: 0 },
      { x: 500, y: 320, r: 118, rot: 0.5 },
    ];
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.max(320, rect.width);
    const h = Math.max(240, rect.height);
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    const scale = Math.min(w / WORLD.w, h / WORLD.h);
    this.view = { scale, ox: (w - WORLD.w * scale) / 2, oy: (h - WORLD.h * scale) / 2, dpr, w, h };
  }

  toWorld(clientX, clientY) {
    const rect = this.canvas.getBoundingClientRect();
    const { scale, ox, oy } = this.view;
    return { x: (clientX - rect.left - ox) / scale, y: (clientY - rect.top - oy) / scale };
  }

  pick(state, clientX, clientY) {
    const p = this.toWorld(clientX, clientY);
    if (state.mode === 'battle' && state.battle) {
      let best = null; let bd = 40;
      for (const u of state.battle.units) {
        if (!u.alive) continue;
        const d = Math.hypot(u.x - p.x, (u.y - 40) - p.y);
        if (d < bd) { bd = d; best = u; }
      }
      return best ? { unit: best } : null;
    }
    // slot proximity
    let best = null; let bd = 62;
    for (let lane = 0; lane < 5; lane++) {
      for (const row of ['front', 'back']) {
        const x = LANE_X[lane]; const y = SLOT_Y.player[row];
        const d = Math.hypot(x - p.x, y - p.y);
        if (d < bd) { bd = d; best = { lane, row, x, y }; }
      }
    }
    if (best) best.key = `${best.lane}-${best.row}`;
    return best;
  }

  hovered(state, clientX, clientY) {
    return this.pick(state, clientX, clientY);
  }

  resetFx() {
    this.fx = []; this.floats = []; this.projectiles = []; this.souls = []; this.shake = 0;
  }

  burst(x, y, color, n = 8, power = 60) {
    for (let i = 0; i < n; i++) {
      const a = rnd(0, Math.PI * 2);
      const sp = rnd(power * 0.3, power);
      this.fx.push({
        type: 'spark', x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 10,
        life: rnd(0.3, 0.65), max: 0.65, color, size: rnd(1.2, 2.8), grav: 90,
      });
    }
  }

  ring(x, y, color, r = 8, size = 46, life = 0.5, flat = 0.4) {
    this.fx.push({ type: 'ring', x, y, r, size, color, life, max: life, flat });
  }

  float(x, y, text, color, size = 15) {
    this.floats.push({ x, y, text, color, life: 0.95, max: 0.95, size, vy: -34 });
  }

  ingest(events) {
    for (const e of events) {
      switch (e.type) {
        case 'hit': {
          this.float(e.x, e.y - 6, `${e.amount}`, e.crit ? '#ffd46e' : e.side === 'player' ? '#ffb0b8' : '#ffffff', e.crit ? 21 : 15);
          this.burst(e.x, e.y, e.crit ? '#ffd46e' : '#ffd9c0', e.crit ? 10 : 5, e.crit ? 110 : 60);
          this.ring(e.x, e.y, e.crit ? '#ffd46e' : 'rgba(255,255,255,.5)', 4, e.crit ? 28 : 17, 0.32, 0.6);
          if (e.crit) this.shake = Math.max(this.shake, 2.4);
          break;
        }
        case 'shieldHit': {
          this.float(e.x, e.y - 4, `⛊ ${e.amount}`, '#9fc4ff', 12);
          this.burst(e.x, e.y, '#9fc4ff', 4, 40);
          break;
        }
        case 'dot': {
          this.float(e.x, e.y, `${e.amount}`, e.color, 11);
          this.burst(e.x, e.y + 4, e.color, 3, 24);
          break;
        }
        case 'thorns': {
          this.float(e.x, e.y, `${e.amount}`, '#ffb276', 11);
          this.burst(e.x, e.y, '#ffb276', 4, 40);
          break;
        }
        case 'heal': {
          this.float(e.x, e.y, `+${e.amount}`, '#7beaa6', 14);
          for (let i = 0; i < 4; i++) {
            this.fx.push({
              type: 'spark', x: e.x + rnd(-14, 14), y: e.y + rnd(-6, 10), vx: rnd(-8, 8), vy: rnd(-60, -24),
              life: 0.7, max: 0.7, color: '#7beaa6', size: rnd(1.4, 2.4), grav: -10,
            });
          }
          this.ring(e.x, e.y, '#7beaa6', 6, 26, 0.5, 0.5);
          break;
        }
        case 'dodge': {
          this.float(e.x, e.y, 'MISS', '#d9d2ff', 12);
          break;
        }
        case 'slash': {
          this.fx.push({
            type: 'slash', x: e.tx, y: e.ty, x0: e.x, y0: e.y,
            color: e.color, life: 0.24, max: 0.24,
          });
          this.burst(e.tx, e.ty, '#ffd9b0', 3, 34);
          break;
        }
        case 'flurry': {
          this.ring(e.x, e.y, e.color, 10, 38, 0.3, 0.7);
          break;
        }
        case 'shot': {
          this.projectiles.push({
            x0: e.x, y0: e.y, x: e.x, y: e.y,
            tx: e.tx, ty: e.ty, t: 0, dur: rnd(0.16, 0.26), color: e.color,
          });
          break;
        }
        case 'cast': {
          this.fx.push({
            type: 'cast', x: e.x, y: e.y, color: e.color, ability: e.ability,
            kind: e.kind, points: e.points || [], life: 1.0, max: 1.0, side: e.side,
          });
          this.ring(e.x, e.y + 10, e.color, 10, 74, 0.8, 0.35);
          this.burst(e.x, e.y + 6, e.color, 12, 80);
          this.shake = Math.max(this.shake, 5);
          break;
        }
        case 'death': {
          this.burst(e.x, e.y + 10, e.color, 16, 95);
          this.ring(e.x, e.y + 10, e.color, 6, 54, 0.8, 0.5);
          this.float(e.x, e.y - 20, 'SLAIN', '#ff8d9a', 12);
          this.shake = Math.max(this.shake, 3.5);
          break;
        }
        case 'nexus': {
          this.fx.push({ type: 'nexus', x: e.x, y: e.y, color: TEAM[e.side === 'player' ? 'enemy' : 'player'], life: 0.7, max: 0.7, from: e.from });
          this.burst(e.x, e.y, e.side === 'player' ? '#ff7b86' : '#5fe3d1', 12, 90);
          this.shake = Math.max(this.shake, 8);
          this.flashRed = Math.max(this.flashRed, 0.25);
          break;
        }
        case 'nexusStrike': {
          const gy = e.side === 'player' ? GATE_Y.enemy : GATE_Y.player;
          this.fx.push({
            type: 'beam', x0: e.x, y0: e.y, x1: e.x, y1: gy,
            color: e.color, life: 0.5, max: 0.5, width: 4,
          });
          break;
        }
        case 'laneBreak': {
          this.fx.push({
            type: 'laneBreak', lane: e.lane, color: e.color,
            side: e.side, life: 1.6, max: 1.6,
          });
          this.shake = Math.max(this.shake, 5);
          break;
        }
        case 'bloodrush': {
          this.fx.push({ type: 'bloodrush', life: 2.4, max: 2.4 });
          break;
        }
        default: break;
      }
    }
  }

  updateFx(dt) {
    this.time += dt;
    this.pulse = (Math.sin(this.time * 2.4) + 1) / 2;
    this.shake = Math.max(0, this.shake - dt * 30);
    this.flashRed = Math.max(0, this.flashRed - dt * 0.8);

    for (const p of this.projectiles) {
      p.t += dt;
      const k = clamp(p.t / p.dur, 0, 1);
      const e = k * (2 - k);
      p.x = p.x0 + (p.tx - p.x0) * e;
      p.y = p.y0 + (p.ty - p.y0) * e - Math.sin(k * Math.PI) * 16;
    }
    this.projectiles = this.projectiles.filter((p) => p.t < p.dur + 0.05);

    for (const f of this.fx) {
      f.life -= dt;
      if (f.type === 'spark') {
        f.x += f.vx * dt; f.y += f.vy * dt;
        f.vy += f.grav * dt;
        f.vx *= 1 - dt * 2;
      }
    }
    this.fx = this.fx.filter((f) => f.life > 0);

    for (const f of this.floats) {
      f.life -= dt; f.y += f.vy * dt; f.vy *= 1 - dt * 2.6;
    }
    this.floats = this.floats.filter((f) => f.life > 0);

    // ambient
    for (const m of this.motes) {
      m.y -= m.sp * dt;
      m.x += Math.sin(this.time * 0.5 + m.ph) * dt * 6;
      if (m.y < 20) { m.y = 610; m.x = rnd(20, 980); }
    }
  }

  // ══ ARENA BACKDROP ════════════════════════════════════════════════════════
  drawBackdrop(ctx, t, state) {
    const battle = state.battle;
    const bg = ctx.createLinearGradient(0, 0, 0, WORLD.h);
    bg.addColorStop(0, '#080b14');
    bg.addColorStop(0.45, '#0a1420');
    bg.addColorStop(1, '#071019');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, WORLD.w, WORLD.h);

    // ambient side glows
    let g = ctx.createRadialGradient(500, 640, 20, 500, 640, 460);
    g.addColorStop(0, 'rgba(70,220,200,.10)'); g.addColorStop(1, 'rgba(70,220,200,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 1000, 620);
    g = ctx.createRadialGradient(500, -10, 20, 500, -10, 420);
    g.addColorStop(0, 'rgba(255,80,100,.09)'); g.addColorStop(1, 'rgba(255,80,100,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 1000, 620);

    // arena floor slab
    const floorGrad = ctx.createLinearGradient(0, 20, 0, 604);
    floorGrad.addColorStop(0, '#101826');
    floorGrad.addColorStop(0.5, '#0c141f');
    floorGrad.addColorStop(1, '#0d1722');
    rr(ctx, 24, 22, 952, 576, 20);
    ctx.fillStyle = floorGrad; ctx.fill();
    ctx.strokeStyle = 'rgba(140,215,255,.14)'; ctx.lineWidth = 2; ctx.stroke();
    rr(ctx, 30, 28, 940, 564, 16);
    ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = 1; ctx.stroke();

    // subtle stone tiling
    ctx.save();
    rr(ctx, 30, 28, 940, 564, 16); ctx.clip();
    for (let i = 0; i < 9; i++) {
      ctx.beginPath();
      ctx.moveTo(30 + i * 120, 28); ctx.lineTo(30 + i * 120 - 90, 592);
      ctx.strokeStyle = 'rgba(120,190,230,.028)'; ctx.lineWidth = 1; ctx.stroke();
    }
    for (let i = 0; i < 7; i++) {
      ctx.beginPath(); ctx.moveTo(24, 60 + i * 82); ctx.lineTo(976, 60 + i * 82);
      ctx.strokeStyle = 'rgba(120,190,230,.03)'; ctx.lineWidth = 1; ctx.stroke();
    }
    // center sigil
    ctx.save(); ctx.translate(500, 320);
    ctx.rotate(t * 0.03);
    ctx.strokeStyle = 'rgba(120,230,230,.055)';
    ctx.lineWidth = 1.2;
    for (const r of [96, 106, 150]) { ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke(); }
    for (let i = 0; i < 8; i++) {
      const a = i * Math.PI / 4;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 106, Math.sin(a) * 106);
      ctx.lineTo(Math.cos(a) * 150, Math.sin(a) * 150);
      ctx.stroke();
    }
    ctx.font = '700 13px Cinzel, serif';
    ctx.fillStyle = 'rgba(120,220,230,.065)';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText('THE SPLICING PIT', 0, 0);
    ctx.restore();
    ctx.restore();

    // lanes
    for (let lane = 0; lane < 5; lane++) {
      const x = LANE_X[lane];
      const laneGrad = ctx.createLinearGradient(0, 30, 0, 596);
      laneGrad.addColorStop(0, 'rgba(255,92,108,.045)');
      laneGrad.addColorStop(0.46, 'rgba(140,200,255,.018)');
      laneGrad.addColorStop(1, 'rgba(95,227,209,.055)');
      rr(ctx, x - 76, 34, 152, 554, 14);
      ctx.fillStyle = laneGrad; ctx.fill();
      ctx.strokeStyle = 'rgba(150,215,255,.06)'; ctx.lineWidth = 1; ctx.stroke();

      // lane divider runes
      for (let i = 0; i < 5; i++) {
        const y = 110 + i * 105;
        ctx.save(); ctx.translate(x - 76, y); ctx.rotate(Math.PI / 4);
        ctx.fillStyle = 'rgba(120,230,230,.10)';
        ctx.fillRect(-2, -2, 4, 4);
        ctx.restore();
      }
      // lane numeral at the bottom
      ctx.save();
      ctx.font = '700 16px Cinzel, serif';
      ctx.fillStyle = 'rgba(150,225,235,.32)';
      ctx.textAlign = 'center';
      ctx.fillText(LANE_ROMAN[lane], x, 584);
      ctx.restore();
    }

    // center divider
    ctx.save();
    ctx.setLineDash([3, 12]);
    ctx.beginPath(); ctx.moveTo(34, 310); ctx.lineTo(966, 310);
    ctx.strokeStyle = 'rgba(160,230,255,.09)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.restore();

    // side pillars and braziers
    this.drawBrazier(ctx, 46, 138, t, '#ffb35c');
    this.drawBrazier(ctx, 954, 138, t, '#ffb35c');
    this.drawBrazier(ctx, 46, 500, t, '#63f0d8');
    this.drawBrazier(ctx, 954, 500, t, '#63f0d8');

    // gates
    this.drawGate(ctx, 'enemy', t, battle);
    this.drawGate(ctx, 'player', t, battle);

    // ambient motes
    for (const m of this.motes) {
      ctx.globalAlpha = 0.24 + Math.sin(t * 1.4 + m.ph) * 0.16;
      ctx.fillStyle = m.hue;
      ctx.beginPath(); ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2); ctx.fill();
    }
    ctx.globalAlpha = 1;

    // edge vignette
    const vg = ctx.createRadialGradient(500, 300, 220, 500, 300, 600);
    vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(2,4,8,.5)');
    ctx.fillStyle = vg; ctx.fillRect(0, 0, 1000, 620);
  }

  drawBrazier(ctx, x, y, t, color) {
    ctx.save();
    ctx.translate(x, y);
    // bowl
    ctx.beginPath(); ctx.moveTo(-11, 0); ctx.lineTo(11, 0); ctx.lineTo(7, 10); ctx.lineTo(-7, 10); ctx.closePath();
    ctx.fillStyle = '#1a2731'; ctx.fill();
    ctx.strokeStyle = 'rgba(160,220,240,.2)'; ctx.lineWidth = 1; ctx.stroke();
    // flame
    const f = Math.sin(t * 7 + x) * 2;
    ctx.globalCompositeOperation = 'lighter';
    const fg = ctx.createRadialGradient(0, -6, 0, 0, -6, 26);
    fg.addColorStop(0, rgba(color, 0.9)); fg.addColorStop(0.35, rgba(color, 0.35)); fg.addColorStop(1, rgba(color, 0));
    ctx.fillStyle = fg;
    ctx.beginPath(); ctx.ellipse(0, -8, 17 + f, 26 + f, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(255,245,220,.9)';
    ctx.beginPath();
    ctx.moveTo(-4, -2); ctx.quadraticCurveTo(-3, -16 - f, 1, -22 - f); ctx.quadraticCurveTo(5, -12, 4, -2); ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  drawGate(ctx, side, t, battle) {
    const gy = GATE_Y[side];
    const color = TEAM[side];
    const isTop = side === 'enemy';
    const nexus = battle ? (side === 'player' ? battle.playerNexus : battle.enemyNexus) : 120;
    const hpFrac = nexus / 120;
    ctx.save();
    // wall band
    const g = ctx.createLinearGradient(0, isTop ? 0 : 590, 0, isTop ? 30 : 620);
    g.addColorStop(0, isTop ? '#0e1a26' : '#132230');
    g.addColorStop(1, isTop ? '#080d15' : '#0a111a');
    ctx.fillStyle = g;
    ctx.fillRect(26, isTop ? 0 : 592, 948, 28);
    ctx.strokeStyle = rgba(color, 0.22); ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(26, isTop ? 28 : 592); ctx.lineTo(974, isTop ? 28 : 592); ctx.stroke();

    // pylons at each lane
    for (let lane = 0; lane < 5; lane++) {
      const x = LANE_X[lane];
      const pulse = 0.55 + Math.sin(t * 2.2 + lane) * 0.2 + (1 - hpFrac) * 0.3;
      ctx.save();
      ctx.translate(x, gy);
      ctx.globalCompositeOperation = 'lighter';
      const cg = ctx.createRadialGradient(0, 0, 2, 0, 0, 44);
      cg.addColorStop(0, rgba(color, 0.55 * pulse));
      cg.addColorStop(0.4, rgba(color, 0.16 * pulse));
      cg.addColorStop(1, rgba(color, 0));
      ctx.fillStyle = cg;
      ctx.beginPath(); ctx.arc(0, 0, 44, 0, Math.PI * 2); ctx.fill();
      ctx.restore();

      // shrine / crystal
      ctx.save(); ctx.translate(x, gy);
      ctx.beginPath();
      ctx.moveTo(0, -14); ctx.lineTo(11, -3); ctx.lineTo(6, 12); ctx.lineTo(-6, 12); ctx.lineTo(-11, -3); ctx.closePath();
      ctx.fillStyle = rgba(color, 0.22 + hpFrac * 0.25); ctx.fill();
      ctx.strokeStyle = rgba(color, 0.7); ctx.lineWidth = 1.4; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(0, 7); ctx.strokeStyle = rgba('#ffffff', 0.45); ctx.lineWidth = 1; ctx.stroke();
      ctx.restore();
    }

    ctx.font = '700 9px Rajdhani, sans-serif';
    ctx.fillStyle = rgba(color, 0.6);
    ctx.textAlign = 'center';
    ctx.letterSpacing = '3px';
    ctx.fillText(side === 'player' ? 'YOUR NEXUS' : 'ENEMY NEXUS', 500, isTop ? 15 : 613);
    ctx.letterSpacing = '0px';
    ctx.restore();
  }

  drawSlot(ctx, x, y, lane, row, side, state, opts = {}) {
    const key = `${lane}-${row}`;
    const hovered = state.hover && state.hover.key === key;
    const selected = state.selectedId && state.slots[key] === state.selectedId;
    const occupied = !!state.slots[key];
    const isEnemy = side === 'enemy';
    const color = isEnemy ? TEAM.enemy : TEAM.player;
    ctx.save();
    ctx.translate(x, y + 2);
    ctx.scale(1, 0.42);
    const r = 36;
    const pulse = 0.5 + Math.sin(this.time * 2 + lane + (row === 'back' ? 1 : 0)) * 0.12;
    const active = hovered || selected || (state.selectedId && !occupied && !isEnemy);
    ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.fillStyle = active ? rgba(color, 0.13) : 'rgba(255,255,255,.018)';
    ctx.fill();
    ctx.strokeStyle = rgba(color, active ? 0.65 : 0.18);
    ctx.lineWidth = hovered ? 2.4 : 1.2;
    ctx.setLineDash(active ? [] : [5, 7]);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.beginPath(); ctx.arc(0, 0, r - 7, 0, Math.PI * 2);
    ctx.strokeStyle = rgba(color, active ? 0.25 : 0.08); ctx.lineWidth = 1; ctx.stroke();
    // inner rune
    ctx.rotate(Math.PI / 4);
    ctx.strokeStyle = rgba(color, active ? 0.5 : 0.12); ctx.lineWidth = 1;
    ctx.strokeRect(-9, -9, 18, 18);
    ctx.restore();

    if (active) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const glow = ctx.createRadialGradient(x, y, 4, x, y, 58);
      glow.addColorStop(0, rgba(color, 0.16)); glow.addColorStop(1, rgba(color, 0));
      ctx.fillStyle = glow;
      ctx.beginPath(); ctx.arc(x, y, 58, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }

    if (row === 'front' && !isEnemy) {
      ctx.font = '600 8px Rajdhani, sans-serif';
      ctx.fillStyle = 'rgba(140,190,210,.28)';
      ctx.textAlign = 'center';
      ctx.fillText('FRONT', x, y + 28);
    }
    if (row === 'back' && !isEnemy) {
      ctx.font = '600 8px Rajdhani, sans-serif';
      ctx.fillStyle = 'rgba(140,190,210,.24)';
      ctx.textAlign = 'center';
      ctx.fillText('BACK', x, y + 28);
    }
  }

  drawHpBar(ctx, u, y, small = false) {
    const w = small ? 48 : 62;
    const h = small ? 4 : 5.5;
    const x = u.x - w / 2;
    const frac = clamp(u.hp / u.maxHp, 0, 1);
    const color = frac > 0.55 ? '#6ee7a8' : frac > 0.28 ? '#f4c96b' : '#ff6d7e';
    ctx.save();
    rr(ctx, x - 1, y - 1, w + 2, h + 2, (h + 2) / 2);
    ctx.fillStyle = 'rgba(4,8,12,.82)'; ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,.6)'; ctx.lineWidth = 1; ctx.stroke();
    if (frac > 0) {
      rr(ctx, x, y, Math.max(1.5, w * frac), h, h / 2);
      ctx.fillStyle = color; ctx.fill();
      rr(ctx, x, y, Math.max(1.5, w * frac), h / 2, h / 2);
      ctx.fillStyle = 'rgba(255,255,255,.22)'; ctx.fill();
    }
    if (u.shield > 0) {
      const sw = w * clamp(u.shield / u.maxHp, 0, 1);
      rr(ctx, x, y - 3, sw, 2, 1);
      ctx.fillStyle = '#9fc4ff'; ctx.fill();
    }
    // tier pips
    const team = u.side === 'player' ? TEAM.player : TEAM.enemy;
    for (let i = 0; i < u.tier; i++) {
      diamond(ctx, x - 8 - i * 7, y + h / 2, 2.2);
      ctx.fillStyle = i === 0 ? team : 'rgba(240,200,121,.8)'; ctx.fill();
    }
    // status
    let sx = x + w + 6;
    const dot = (c) => { ctx.beginPath(); ctx.arc(sx, y + h / 2, 2.4, 0, Math.PI * 2); ctx.fillStyle = c; ctx.fill(); sx += 6; };
    if (u.poison && u.poison.length) dot('#b8ef6a');
    if (u.burn) dot('#ff9a5c');
    if (u.status && u.status.slowUntil > this.time) dot('#9be8ff');
    if (u.status && u.status.stunUntil > this.time) dot('#ffd46e');
    if (u.status && u.status.atkBuffUntil > this.time) dot('#ffcf6e');
    ctx.restore();
  }

  drawUnit(ctx, u, state, scaleMul = 1, preview = false) {
    const art = u.ref.art;
    const scale = 0.72 * (art.scale || 1) * scaleMul;
    const dir = u.side === 'player' ? -1 : 1;
    const lunge = preview ? 0 : (u.lunge || 0) * 6 * dir;
    const alpha = u.alive === false ? 0.25 : 1;
    const x = u.x;
    const y = u.y + lunge;
    drawCreature(ctx, art, x, y, scale, {
      time: this.time,
      seed: (u.lane + 1) * 1.7 + (u.side === 'enemy' ? 2.3 : 0),
      team: u.side,
      flash: u.flash || 0,
      alpha,
      ring: true,
      bob: u.walking ? 1.6 : 0.8,
    });

    if (preview) return;

    // energy ring at feet
    if (u.energy != null) {
      const pct = clamp(u.energy / 100, 0, 1);
      const color = u.side === 'player' ? TEAM.player : TEAM.enemy;
      ctx.save();
      ctx.translate(x, y + 3); ctx.scale(1, 0.4);
      ctx.beginPath();
      ctx.arc(0, 0, 27, -Math.PI / 2, -Math.PI / 2 + pct * Math.PI * 2);
      ctx.strokeStyle = u.energy >= 100 ? '#ffe08a' : rgba(color, 0.7);
      ctx.lineWidth = 2.4;
      if (u.energy >= 100) { ctx.shadowColor = '#ffe08a'; ctx.shadowBlur = 8; }
      ctx.stroke();
      ctx.restore();
    }

    // shield ring
    if (u.shield > 0) {
      ctx.save();
      ctx.translate(x, y - 40);
      ctx.strokeStyle = 'rgba(159,196,255,.5)';
      ctx.lineWidth = 1.4;
      hexPath(ctx, 0, 0, 33 + Math.sin(this.time * 3) * 2);
      ctx.stroke();
      ctx.restore();
    }

    // stun stars
    if (u.status && u.status.stunUntil > this.time) {
      ctx.save();
      for (let i = 0; i < 3; i++) {
        const a = this.time * 3 + i * 2.1;
        const sx = x + Math.cos(a) * 22;
        const sy = y - 74 + Math.sin(a) * 5;
        ctx.fillStyle = 'rgba(255,225,140,.9)';
        diamond(ctx, sx, sy, 2.4); ctx.fill();
      }
      ctx.restore();
    }

    // ready halo
    if (u.energy >= 100) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const rg = ctx.createRadialGradient(x, y - 60, 6, x, y - 60, 42);
      rg.addColorStop(0, 'rgba(255,224,138,.22)'); rg.addColorStop(1, 'rgba(255,224,138,0)');
      ctx.fillStyle = rg;
      ctx.beginPath(); ctx.arc(x, y - 60, 42, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
      ctx.save();
      ctx.fillStyle = '#ffe08a';
      ctx.shadowColor = '#ffe08a'; ctx.shadowBlur = 8;
      diamond(ctx, x, y - 100 - Math.sin(this.time * 3) * 3, 4); ctx.fill();
      ctx.restore();
    }

    this.drawHpBar(ctx, u, y - (art.feats.has('bulk') ? 88 : 84));
  }

  // ══ MAIN RENDER ═══════════════════════════════════════════════════════════
  render(state, dt) {
    this.updateFx(dt);
    const ctx = this.ctx;
    const { dpr, w, h, scale, ox, oy } = this.view;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    ctx.fillStyle = '#050810';
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

    const shakeX = this.shake ? rnd(-this.shake, this.shake) : 0;
    const shakeY = this.shake ? rnd(-this.shake, this.shake) * 0.6 : 0;
    ctx.setTransform(dpr, 0, 0, dpr, dpr * (ox + shakeX * scale), dpr * (oy + shakeY * scale));
    ctx.scale(scale, scale);
    ctx.save();
    ctx.beginPath(); ctx.rect(0, 0, 1000, 620); ctx.clip();

    const t = this.time;
    this.drawBackdrop(ctx, t, state);

    // slots
    for (let lane = 0; lane < 5; lane++) {
      for (const row of ['back', 'front']) {
        this.drawSlot(ctx, LANE_X[lane], SLOT_Y.player[row], lane, row, 'player', state);
        this.drawSlot(ctx, LANE_X[lane], SLOT_Y.enemy[row], lane, row, 'enemy', state);
      }
    }

    if (state.mode === 'prep') {
      this.drawPrep(ctx, state, t);
    } else if (state.battle) {
      this.drawBattle(ctx, state, t);
    }

    // floats on top
    for (const f of this.floats) {
      const a = clamp(f.life / f.max, 0, 1);
      ctx.save();
      ctx.globalAlpha = a;
      ctx.font = `700 ${f.size}px Rajdhani, sans-serif`;
      ctx.textAlign = 'center';
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(4,8,12,.8)';
      ctx.strokeText(f.text, f.x, f.y);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, f.x, f.y);
      ctx.restore();
    }

    // vignette over units for cohesion
    const vg = ctx.createRadialGradient(500, 310, 300, 500, 310, 590);
    vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(2,4,8,.28)');
    ctx.fillStyle = vg; ctx.fillRect(0, 0, 1000, 620);

    if (this.flashRed > 0.01) {
      ctx.fillStyle = `rgba(255,40,60,${this.flashRed * 0.5})`;
      ctx.fillRect(0, 0, 1000, 620);
    }
    for (const f of this.fx.filter((f) => f.type === 'bloodrush')) {
      ctx.fillStyle = `rgba(255,40,50,${0.08 + Math.sin(t * 8) * 0.04})`;
      ctx.fillRect(0, 0, 1000, 620);
    }
    ctx.restore();
  }

  drawPrep(ctx, state, t) {
    // enemy intel
    if (state.enemies) {
      for (const e of state.enemies) {
        const x = LANE_X[e.lane]; const y = SLOT_Y.enemy[e.row];
        ctx.save(); ctx.globalAlpha = 0.9;
        const fake = {
          x, y, side: 'enemy', lane: e.lane, row: e.row, ref: e.unit,
          flash: 0, walking: false, energy: 0, shield: 0, alive: true,
          status: { stunUntil: 0, slowUntil: 0, atkBuffUntil: 0 },
          hp: e.unit.stats.hp, maxHp: e.unit.stats.hp, tier: e.unit.tier,
        };
        this.drawUnit(ctx, fake, state, 0.94, false);
        ctx.font = '600 9px Rajdhani, sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = 'rgba(255,150,160,.85)';
        ctx.fillText(e.unit.name.toUpperCase(), x, y + 30);
        ctx.restore();
      }
    }

    // deployed player units
    for (const [key, id] of Object.entries(state.slots || {})) {
      if (!id) continue;
      const [laneS, row] = key.split('-');
      const lane = Number(laneS);
      const ru = state.roster.find((u) => u.id === id);
      if (!ru) continue;
      const selected = state.selectedId === id;
      const x = LANE_X[lane]; const y = SLOT_Y.player[row];
      const fake = {
        x, y, side: 'player', lane, row, ref: ru,
        flash: 0, walking: false, energy: 0, shield: 0, alive: true,
        status: { stunUntil: 0, slowUntil: 0, atkBuffUntil: 0 },
        hp: ru.stats.hp, maxHp: ru.stats.hp, tier: ru.tier,
      };
      ctx.save();
      if (selected) {
        ctx.globalCompositeOperation = 'lighter';
        const sg = ctx.createRadialGradient(x, y - 24, 4, x, y - 24, 58);
        sg.addColorStop(0, 'rgba(95,227,209,.16)'); sg.addColorStop(1, 'rgba(95,227,209,0)');
        ctx.fillStyle = sg; ctx.beginPath(); ctx.arc(x, y - 24, 58, 0, Math.PI * 2); ctx.fill();
      }
      ctx.restore();
      this.drawUnit(ctx, fake, state, selected ? 1.02 : 1, false);
      ctx.font = '600 9px Rajdhani, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(150,240,225,.9)';
      ctx.fillText(ru.name.toUpperCase(), x, y + 30);
    }

    // ghost preview for selected unit on hover
    if (state.selectedId && state.hover && state.hover.key) {
      const id = state.selectedId;
      const occupied = state.slots[state.hover.key];
      const ru = state.roster.find((u) => u.id === id);
      if (ru && (!occupied || occupied === id)) {
        const x = state.hover.x; const y = state.hover.y;
        ctx.save(); ctx.globalAlpha = 0.45;
        drawCreature(ctx, ru.art, x, y, 0.72 * (ru.art.scale || 1), {
          time: t, team: 'player', ring: false, animate: true, seed: 3,
        });
        ctx.restore();
      }
    }

    // matchup lines
    for (let lane = 0; lane < 5; lane++) {
      const myId = state.slots[`${lane}-front`] || state.slots[`${lane}-back`];
      const their = (state.enemies || []).find((e) => e.lane === lane);
      if (!myId || !their) continue;
      ctx.save();
      ctx.setLineDash([2, 9]);
      ctx.beginPath();
      ctx.moveTo(LANE_X[lane] + 44, 330);
      ctx.lineTo(LANE_X[lane] + 44, 300);
      ctx.strokeStyle = 'rgba(255,120,140,.22)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.restore();
      ctx.save();
      ctx.fillStyle = 'rgba(255,150,160,.28)';
      ctx.font = '700 8px Rajdhani, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('VS', LANE_X[lane] + 44, 296);
      ctx.restore();
    }
  }

  drawBattle(ctx, state, t) {
    const b = state.battle;
    const units = b.units;
    // dead first
    for (const u of units) {
      if (!u.alive && u.deathT < 1.3) this.drawUnit(ctx, u, state);
    }
    const alive = units.filter((u) => u.alive).sort((a, c) => a.y - c.y);
    for (const u of alive) this.drawUnit(ctx, u, state);

    // projectiles
    for (const p of this.projectiles) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = 'rgba(255,255,255,.25)';
      ctx.lineWidth = 5;
      ctx.beginPath(); ctx.moveTo(p.x0, p.y0); ctx.lineTo(p.x, p.y); ctx.stroke();
      ctx.strokeStyle = p.color; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(p.x0, p.y0); ctx.lineTo(p.x, p.y); ctx.stroke();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(p.x, p.y, 2.6, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }

    // effects
    for (const f of this.fx) this.drawFx(ctx, f, t);

    // lane break indicators
    for (const f of this.fx) {
      if (f.type !== 'laneBreak') continue;
      const a = clamp(f.life / f.max, 0, 1);
      const y = f.side === 'player' ? GATE_Y.enemy : GATE_Y.player;
      ctx.save();
      ctx.globalAlpha = a;
      ctx.strokeStyle = f.color; ctx.lineWidth = 2;
      ctx.shadowColor = f.color; ctx.shadowBlur = 12;
      ctx.beginPath(); ctx.arc(LANE_X[f.lane], y, 26 + (1 - a) * 16, 0, Math.PI * 2); ctx.stroke();
      ctx.restore();
    }
  }

  drawFx(ctx, f, t) {
    const a = clamp(f.life / f.max, 0, 1);
    if (f.type === 'spark') {
      ctx.globalAlpha = a;
      ctx.fillStyle = f.color;
      ctx.beginPath(); ctx.arc(f.x, f.y, f.size * a, 0, Math.PI * 2); ctx.fill();
      ctx.globalAlpha = 1;
    } else if (f.type === 'ring') {
      ctx.save();
      ctx.globalAlpha = a * 0.8;
      ctx.translate(f.x, f.y);
      ctx.scale(1, f.flat);
      const rr = f.r + (1 - a) * f.size;
      ctx.beginPath(); ctx.arc(0, 0, rr, 0, Math.PI * 2);
      ctx.strokeStyle = f.color; ctx.lineWidth = 2 + a * 2;
      ctx.shadowColor = f.color; ctx.shadowBlur = 8;
      ctx.stroke();
      ctx.restore();
    } else if (f.type === 'slash') {
      ctx.save();
      ctx.globalAlpha = a;
      const mx = (f.x + f.x0) / 2; const my = (f.y + f.y0) / 2;
      ctx.translate(mx, my);
      ctx.rotate(Math.atan2(f.y - f.y0, f.x - f.x0) + Math.PI / 2);
      ctx.beginPath(); ctx.arc(0, 0, 24, -1.1, 1.3);
      ctx.strokeStyle = '#fff7e6'; ctx.lineWidth = 3.4; ctx.lineCap = 'round';
      ctx.shadowColor = f.color; ctx.shadowBlur = 12;
      ctx.stroke();
      ctx.strokeStyle = f.color; ctx.lineWidth = 1.2; ctx.stroke();
      ctx.restore();
    } else if (f.type === 'beam') {
      const k = 1 - a;
      ctx.save();
      ctx.globalAlpha = a;
      ctx.strokeStyle = f.color; ctx.lineWidth = f.width || 4;
      ctx.shadowColor = f.color; ctx.shadowBlur = 14;
      ctx.beginPath(); ctx.moveTo(f.x0, f.y0); ctx.lineTo(f.x1, f.y1); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,.6)'; ctx.lineWidth = 1.5; ctx.stroke();
      ctx.restore();
    } else if (f.type === 'cast') {
      this.drawCastFx(ctx, f, a, t);
    } else if (f.type === 'nexus') {
      ctx.save();
      const r = 20 + (1 - a) * 60;
      ctx.globalAlpha = a;
      ctx.globalCompositeOperation = 'lighter';
      ctx.beginPath(); ctx.arc(f.x, f.y, r, 0, Math.PI * 2);
      const g = ctx.createRadialGradient(f.x, f.y, 2, f.x, f.y, r);
      g.addColorStop(0, 'rgba(255,255,255,.8)'); g.addColorStop(0.4, f.color); g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g; ctx.fill();
      ctx.restore();
    } else if (f.type === 'bloodrush') {
      // handled globally
    }
  }

  drawCastFx(ctx, f, a, t) {
    const fade = a;
    const c = f.color;
    const p = 1 - a;
    ctx.save();
    // central pillar
    ctx.globalAlpha = fade * 0.9;
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(f.x, f.y, 2, f.x, f.y, 60 + p * 30);
    g.addColorStop(0, rgba(c, 0.55)); g.addColorStop(0.5, rgba(c, 0.12)); g.addColorStop(1, rgba(c, 0));
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(f.x, f.y, 60 + p * 30, 0, Math.PI * 2); ctx.fill();
    ctx.restore();

    // connectors to affected points
    if (f.points && f.points.length) {
      ctx.save();
      ctx.globalAlpha = fade * 0.7;
      ctx.globalCompositeOperation = 'lighter';
      ctx.lineWidth = 2;
      ctx.strokeStyle = c;
      ctx.shadowColor = c; ctx.shadowBlur = 10;
      for (const pt of f.points) {
        ctx.beginPath(); ctx.moveTo(f.x, f.y); ctx.lineTo(pt.x, pt.y); ctx.stroke();
        ctx.beginPath(); ctx.arc(pt.x, pt.y, 10 + p * 12, 0, Math.PI * 2); ctx.stroke();
      }
      ctx.restore();
    }

    ctx.save();
    ctx.globalAlpha = fade;
    ctx.translate(f.x, f.y);
    ctx.strokeStyle = c; ctx.lineWidth = 2;
    ctx.shadowColor = c; ctx.shadowBlur = 10;

    switch (f.ability) {
      case 'howl': {
        for (let i = 0; i < 3; i++) {
          const rr = 26 + i * 18 + p * 50;
          ctx.beginPath(); ctx.arc(0, 0, rr, 0, Math.PI * 2); ctx.stroke();
        }
        for (let i = 0; i < 8; i++) {
          const ang = i / 8 * Math.PI * 2 + t;
          ctx.beginPath(); ctx.moveTo(Math.cos(ang) * 20, Math.sin(ang) * 20);
          ctx.lineTo(Math.cos(ang) * (34 + p * 26), Math.sin(ang) * (34 + p * 26)); ctx.stroke();
        }
        break;
      }
      case 'shockwave': {
        ctx.scale(1, 0.45);
        for (let i = 0; i < 3; i++) {
          ctx.beginPath(); ctx.arc(0, 0, 30 + i * 22 + p * 90, 0, Math.PI * 2);
          ctx.strokeStyle = rgba('#ffb35e', fade * (0.8 - i * 0.2)); ctx.stroke();
        }
        break;
      }
      case 'breath': {
        const dir = f.side === 'player' ? -1 : 1;
        ctx.scale(1, dir);
        const fg = ctx.createLinearGradient(0, 0, 0, -120);
        fg.addColorStop(0, rgba('#ffe0a0', 0.55 * fade)); fg.addColorStop(1, rgba('#ff5c2a', 0));
        ctx.fillStyle = fg;
        ctx.beginPath(); ctx.moveTo(-8, 0); ctx.quadraticCurveTo(-46, -70, 0, -130); ctx.quadraticCurveTo(46, -70, 8, 0); ctx.closePath(); ctx.fill();
        break;
      }
      case 'fortify': {
        for (let i = 0; i < 2; i++) {
          ctx.beginPath(); ctx.arc(0, 0, 34 + i * 18 + p * 30, 0, Math.PI * 2); ctx.stroke();
        }
        break;
      }
      case 'reap': {
        for (let i = 0; i < 3; i++) {
          ctx.rotate(2.1);
          ctx.beginPath(); ctx.arc(0, 0, 36 + p * 30, -0.5, 0.9); ctx.strokeStyle = c; ctx.lineWidth = 3; ctx.stroke();
        }
        break;
      }
      case 'venomNova': {
        for (let i = 0; i < 3; i++) {
          ctx.beginPath(); ctx.arc(0, 0, 24 + i * 16 + p * 40, 0, Math.PI * 2);
          ctx.strokeStyle = rgba('#b9f06a', fade * 0.7); ctx.stroke();
        }
        break;
      }
      default: {
        for (let i = 0; i < 3; i++) {
          ctx.beginPath(); ctx.arc(0, 0, 20 + i * 15 + p * 40, 0, Math.PI * 2);
          ctx.stroke();
        }
        break;
      }
    }
    ctx.restore();
  }
}

// ══ TITLE SCREEN ═══════════════════════════════════════════════════════════
export function renderTitle(canvas, units, time) {
  const ctx = canvas.getContext('2d');
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const rect = canvas.getBoundingClientRect();
  const w = Math.max(320, rect.width); const h = Math.max(240, rect.height);
  if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);

  const bg = ctx.createRadialGradient(w * 0.5, h * 0.52, 20, w * 0.5, h * 0.52, Math.max(w, h) * 0.8);
  bg.addColorStop(0, '#10202b'); bg.addColorStop(0.5, '#08121c'); bg.addColorStop(1, '#04070d');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);

  // distant rays
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 7; i++) {
    const x = w * (0.15 + i * 0.12) + Math.sin(time * 0.2 + i) * 20;
    const g = ctx.createLinearGradient(x, 0, x + 80, h);
    g.addColorStop(0, 'rgba(90,230,210,.05)'); g.addColorStop(1, 'rgba(90,230,210,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x + 90, 0); ctx.lineTo(x + 200, h); ctx.lineTo(x + 40, h); ctx.closePath(); ctx.fill();
  }
  ctx.restore();

  const scale = Math.min(w / 1180, h / 820);
  const baseY = h * 0.86;
  const groundY = baseY;
  ctx.save();
  ctx.translate(w / 2, groundY);
  ctx.scale(scale, scale);

  // platform
  ctx.save(); ctx.scale(1, 0.28);
  const pg = ctx.createRadialGradient(0, 0, 20, 0, 0, 430);
  pg.addColorStop(0, 'rgba(63,220,200,.25)'); pg.addColorStop(0.6, 'rgba(63,220,200,.06)'); pg.addColorStop(1, 'rgba(63,220,200,0)');
  ctx.fillStyle = pg; ctx.beginPath(); ctx.arc(0, 0, 430, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = 'rgba(120,240,225,.3)'; ctx.lineWidth = 2;
  for (const r of [180, 260, 340]) { ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke(); }
  ctx.restore();

  // rune ring behind
  ctx.save();
  ctx.translate(0, -160);
  ctx.rotate(time * 0.05);
  ctx.strokeStyle = 'rgba(120,230,230,.12)'; ctx.lineWidth = 1.4;
  for (let i = 0; i < 2; i++) {
    ctx.beginPath(); ctx.arc(0, 0, 260 + i * 30, 0, Math.PI * 2); ctx.stroke();
  }
  for (let i = 0; i < 16; i++) {
    const a = i / 16 * Math.PI * 2;
    ctx.save(); ctx.translate(Math.cos(a) * 290, Math.sin(a) * 290); ctx.rotate(a);
    ctx.fillStyle = 'rgba(130,240,230,.18)';
    ctx.fillRect(-2, -6, 4, 12);
    ctx.restore();
  }
  ctx.restore();

  // creatures
  const lineup = [
    { u: units[0], x: -280, s: 1.6, t: 0.2 },
    { u: units[1], x: 0, s: 1.95, t: 1.4 },
    { u: units[2], x: 285, s: 1.6, t: 2.6 },
  ];
  for (const item of lineup) {
    if (!item.u) continue;
    const bob = Math.sin(time * 1.2 + item.t) * 5;
    ctx.save();
    ctx.globalAlpha = 0.96;
    const glow = ctx.createRadialGradient(item.x, -80, 20, item.x, -80, 190);
    glow.addColorStop(0, 'rgba(90,240,220,.12)'); glow.addColorStop(1, 'rgba(90,240,220,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(item.x, -80, 190, 0, Math.PI * 2); ctx.fill();
    drawCreature(ctx, item.u.art, item.x, bob, item.s, {
      time, seed: item.t, team: item.u.primary === 'drake' ? 'enemy' : 'player',
      ring: true, animate: true,
    });
    ctx.restore();
  }
  ctx.restore();

  // fog
  ctx.save();
  for (let i = 0; i < 6; i++) {
    const x = ((time * (8 + i * 2) + i * 230) % (w + 400)) - 200;
    const y = h * 0.72 + Math.sin(time * 0.3 + i) * 18 + i * 10;
    const g = ctx.createRadialGradient(x, y, 10, x, y, 180 + i * 20);
    g.addColorStop(0, 'rgba(80,160,170,.055)'); g.addColorStop(1, 'rgba(80,160,170,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.ellipse(x, y, 220, 52, 0, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();

  // floating embers
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 30; i++) {
    const x = (i * 157 + Math.sin(time * 0.4 + i) * 50) % w;
    const y = (h - ((time * (12 + i % 9) + i * 53) % h));
    const a = 0.15 + Math.sin(time * 2 + i) * 0.1;
    ctx.globalAlpha = a;
    ctx.fillStyle = i % 3 ? '#7be8d8' : '#ffcf8a';
    ctx.beginPath(); ctx.arc(x, y, 1.6, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();

  // bottom fade into UI
  const fade = ctx.createLinearGradient(0, h * 0.72, 0, h);
  fade.addColorStop(0, 'rgba(4,7,13,0)'); fade.addColorStop(1, 'rgba(4,7,13,.92)');
  ctx.fillStyle = fade; ctx.fillRect(0, h * 0.72, w, h * 0.28);
  // top vignette
  const top = ctx.createLinearGradient(0, 0, 0, h * 0.35);
  top.addColorStop(0, 'rgba(3,6,10,.8)'); top.addColorStop(1, 'rgba(3,6,10,0)');
  ctx.fillStyle = top; ctx.fillRect(0, 0, w, h * 0.35);
  const vg = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,.55)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, w, h);
}

// ── CHIMERA FRONT · synthesized sound (no assets) ───────────────────────────
export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = localStorage.getItem('chimera-muted') === '1';
    this.last = {};
  }

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(this.ctx.destination);
  }

  setMuted(m) {
    this.muted = m;
    localStorage.setItem('chimera-muted', m ? '1' : '0');
    if (this.master) this.master.gain.value = m ? 0 : 0.5;
  }

  throttle(key, ms = 45) {
    const now = performance.now();
    if (this.last[key] && now - this.last[key] < ms) return false;
    this.last[key] = now;
    return true;
  }

  tone(freq, dur, type = 'sine', vol = 0.2, slide = null, delay = 0) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t0 + dur);
    g.gain.setValueAtTime(0, t0);
    g.gain.linearRampToValueAtTime(vol, t0 + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g); g.connect(this.master);
    osc.start(t0); osc.stop(t0 + dur + 0.02);
  }

  noise(dur, vol = 0.15, freq = 900, delay = 0) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + delay;
    const len = Math.floor(this.ctx.sampleRate * dur);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass'; filter.frequency.value = freq; filter.Q.value = 0.8;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter); filter.connect(g); g.connect(this.master);
    src.start(t0);
  }

  ui() { if (!this.throttle('ui', 60)) return; this.tone(540, 0.06, 'triangle', 0.07, 700); }
  select() { if (!this.throttle('sel', 60)) return; this.tone(680, 0.08, 'triangle', 0.08, 900); }
  deploy() { this.tone(220, 0.16, 'sine', 0.16, 380); this.noise(0.12, 0.06, 600); }
  error() { if (!this.throttle('err', 120)) return; this.tone(160, 0.12, 'square', 0.08, 120); }
  buy() { this.tone(440, 0.09, 'triangle', 0.12); this.tone(660, 0.12, 'triangle', 0.1, null, 0.08); }
  splice() {
    this.tone(180, 0.5, 'sawtooth', 0.08, 520);
    this.tone(240, 0.45, 'triangle', 0.1, 720, 0.12);
    this.noise(0.5, 0.08, 1400);
    [0, 0.1, 0.2, 0.3].forEach((d, i) => this.tone(520 + i * 160, 0.14, 'sine', 0.09, null, 0.28 + d));
  }
  battleStart() {
    this.tone(90, 0.7, 'sine', 0.2, 60);
    this.tone(180, 0.5, 'triangle', 0.08, 240);
    this.noise(0.5, 0.1, 500);
  }
  hit() { if (!this.throttle('hit', 55)) return; this.noise(0.08, 0.06, 1400); this.tone(120, 0.06, 'sine', 0.05, 90); }
  heavy() { if (!this.throttle('heavy', 90)) return; this.noise(0.16, 0.1, 700); this.tone(80, 0.18, 'sine', 0.12, 50); }
  shot() { if (!this.throttle('shot', 65)) return; this.tone(900, 0.07, 'triangle', 0.04, 500); }
  cast() {
    if (!this.throttle('cast', 100)) return;
    this.tone(260, 0.5, 'sawtooth', 0.05, 780);
    this.noise(0.35, 0.08, 1800);
  }
  death() { if (!this.throttle('death', 120)) return; this.tone(160, 0.3, 'triangle', 0.07, 70); }
  nexus() { if (!this.throttle('nexus', 90)) return; this.tone(60, 0.6, 'sine', 0.22, 40); this.noise(0.4, 0.14, 300); }
  alarm() { this.tone(330, 0.18, 'square', 0.06, 220); this.tone(330, 0.18, 'square', 0.06, 220, 0.22); }
  victory() {
    [392, 494, 587, 784].forEach((f, i) => this.tone(f, 0.5, 'triangle', 0.1, null, i * 0.13));
    this.tone(196, 1.2, 'sine', 0.1, 196, 0.1);
  }
  defeat() {
    [330, 294, 247, 196].forEach((f, i) => this.tone(f, 0.55, 'triangle', 0.09, null, i * 0.17));
    this.tone(98, 1.4, 'sine', 0.12, 60, 0.2);
  }
  bloodrush() {
    this.tone(70, 0.7, 'sawtooth', 0.1, 120);
    this.noise(0.6, 0.1, 240);
  }
}

/* ── CHIMERA FRONT · interface ─────────────────────────────────────────────── */
@font-face { font-family: 'Cinzel'; src: url('./assets/fonts/cinzel-latin.woff2') format('woff2'); font-weight: 500 900; font-style: normal; font-display: swap; }
@font-face { font-family: 'Rajdhani'; src: url('./assets/fonts/rajdhani-400.woff2') format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'Rajdhani'; src: url('./assets/fonts/rajdhani-500.woff2') format('woff2'); font-weight: 500; font-display: swap; }
@font-face { font-family: 'Rajdhani'; src: url('./assets/fonts/rajdhani-600.woff2') format('woff2'); font-weight: 600; font-display: swap; }
@font-face { font-family: 'Rajdhani'; src: url('./assets/fonts/rajdhani-700.woff2') format('woff2'); font-weight: 700; font-display: swap; }

:root {
  --bg: #05080f;
  --bg-2: #08111b;
  --panel: rgba(11, 22, 33, .86);
  --panel-2: rgba(15, 29, 43, .82);
  --line: rgba(128, 198, 230, .13);
  --line-strong: rgba(128, 210, 240, .26);
  --txt: #e7f0f8;
  --muted: #91a5bb;
  --dim: #5e738a;
  --cyan: #5fe3d1;
  --cyan-deep: #2bb9ad;
  --gold: #f0c879;
  --gold-2: #f7de9d;
  --red: #ff5c6c;
  --violet: #b496ff;
  --green: #7beaa6;
  --display: 'Cinzel', Georgia, serif;
  --ui: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
  --dock-h: 168px;
  --top-h: 64px;
  --side-w: 324px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  background: var(--bg);
  color: var(--txt);
  font-family: var(--ui);
  font-size: 14px;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button { font-family: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 1px solid var(--cyan); outline-offset: 3px; }
canvas { display: block; }
::selection { background: rgba(95, 227, 209, .3); }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: rgba(255,255,255,.02); }
::-webkit-scrollbar-thumb { background: rgba(130, 190, 220, .18); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: rgba(130, 210, 235, .3); }

.app {
  display: grid;
  grid-template-rows: var(--top-h) minmax(0, 1fr) var(--dock-h);
  height: 100dvh;
  width: 100vw;
  background:
    radial-gradient(1200px 500px at 70% -10%, rgba(54, 130, 150, .10), transparent 60%),
    radial-gradient(900px 460px at 0% 100%, rgba(60, 200, 180, .055), transparent 60%),
    var(--bg);
}

/* ══ TOP BAR ═════════════════════════════════════════════════════════════════ */
.topbar {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 18px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(10, 21, 32, .95), rgba(6, 13, 21, .9));
  position: relative;
  z-index: 20;
  box-shadow: 0 10px 40px rgba(0, 0, 0, .35);
}
.topbar::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -1px; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(95, 227, 209, .4), rgba(240, 200, 121, .2), transparent);
  opacity: .5;
}
.brand { display: flex; align-items: center; gap: 10px; min-width: 232px; }
.brand-mark { width: 32px; height: 32px; color: var(--cyan); filter: drop-shadow(0 0 8px rgba(95,227,209,.45)); }
.brand-mark svg { width: 100%; height: 100%; }
.brand-text h1 {
  font-family: var(--display); font-weight: 700; font-size: 17px;
  letter-spacing: .14em; line-height: 1.05; white-space: nowrap;
  color: #f0f8ff;
}
.brand-text h1 em { font-style: normal; color: var(--cyan); text-shadow: 0 0 18px rgba(95,227,209,.4); }
.brand-text span {
  display: block; font-size: 7.5px; font-weight: 600; letter-spacing: .34em;
  color: var(--dim); margin-top: 3px; white-space: nowrap;
}

.wave-progress { flex: 1; display: flex; align-items: center; justify-content: center; gap: 14px; min-width: 160px; }
.wp-label { font-size: 9px; letter-spacing: .24em; color: var(--dim); font-weight: 600; white-space: nowrap; }
.wp-label b { color: var(--gold); font-size: 11px; font-weight: 700; }
.wp-pips { display: flex; align-items: center; gap: 5px; }
.wp-pip {
  width: 15px; height: 15px; display: grid; place-items: center; position: relative; flex: none;
}
.wp-pip::before {
  content: ''; width: 7px; height: 7px; transform: rotate(45deg);
  border: 1px solid rgba(140, 180, 200, .3); background: rgba(255,255,255,.02);
  transition: all .3s;
}
.wp-pip.done::before { background: rgba(95, 227, 209, .55); border-color: rgba(95, 227, 209, .7); box-shadow: 0 0 7px rgba(95, 227, 209, .5); }
.wp-pip.current::before { background: var(--gold); border-color: var(--gold-2); box-shadow: 0 0 12px rgba(240, 200, 121, .8); animation: pipPulse 1.7s infinite; }
.wp-pip.boss::after {
  content: ''; position: absolute; inset: -3px; border: 1px solid rgba(255, 92, 108, .25);
  transform: rotate(45deg); border-radius: 2px;
}
.wp-pip.boss.done::after { border-color: rgba(255, 92, 108, .5); }
@keyframes pipPulse { 0%,100% { box-shadow: 0 0 6px rgba(240,200,121,.5); } 50% { box-shadow: 0 0 16px rgba(240,200,121,.95); } }

.top-resources { display: flex; align-items: center; gap: 10px; }
.essence-pill {
  display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 12px;
  border: 1px solid rgba(240, 200, 121, .22); border-radius: 6px;
  background: linear-gradient(160deg, rgba(240, 200, 121, .09), rgba(240, 200, 121, .02));
  position: relative;
}
.essence-gem {
  width: 11px; height: 11px; transform: rotate(45deg);
  background: linear-gradient(135deg, #fff0c5, var(--gold) 45%, #a57a2a);
  box-shadow: 0 0 10px rgba(240, 200, 121, .45); border-radius: 1px;
}
#essenceVal { font-size: 20px; font-weight: 700; color: var(--gold-2); line-height: 1; letter-spacing: .02em; min-width: 22px; }
.essence-pill small { font-size: 7px; letter-spacing: .2em; color: rgba(240, 200, 121, .55); font-weight: 600; margin-left: 1px; }
@keyframes essencePop { 0% { transform: scale(1); } 35% { transform: scale(1.35); color: #fff; } 100% { transform: scale(1); } }
#essenceVal.pop { animation: essencePop .4s; }

.nexus-pair { display: grid; gap: 3px; padding: 4px 9px; border-left: 1px solid var(--line); border-right: 1px solid var(--line); }
.nexus-mini { display: flex; align-items: center; gap: 6px; }
.nm-label { font-size: 7px; font-weight: 700; letter-spacing: .15em; color: var(--dim); width: 20px; }
.nm-bar { width: 62px; height: 4px; background: rgba(0,0,0,.55); border-radius: 1px; overflow: hidden; }
.nm-bar i { display: block; height: 100%; width: 100%; transition: width .2s; }
.you .nm-bar i { background: linear-gradient(90deg, #2bb9ad, #7ff5e3); box-shadow: 0 0 6px rgba(95,227,209,.5); }
.foe .nm-bar i { background: linear-gradient(90deg, #b03848, #ff7d8a); box-shadow: 0 0 6px rgba(255,92,108,.45); }
.nm-val { font-size: 9px; font-weight: 600; color: var(--muted); width: 22px; text-align: right; }

.icon-btn {
  width: 32px; height: 32px; display: grid; place-items: center; flex: none;
  border: 1px solid var(--line); border-radius: 6px; background: rgba(255,255,255,.025);
  color: var(--muted); font-weight: 700; font-size: 14px; font-family: var(--ui);
  transition: .18s; position: relative;
}
.icon-btn:hover { color: var(--cyan); border-color: var(--line-strong); background: rgba(95,227,209,.06); }
.icon-btn svg { width: 16px; height: 16px; }
.ic-mute { display: none; }
.muted .ic-mute { display: block; } .muted .ic-sound { display: none; }

/* ══ MAIN ═══════════════════════════════════════════════════════════════════ */
.main {
  display: grid; grid-template-columns: minmax(0, 1fr) var(--side-w);
  gap: 14px; padding: 14px 16px 10px; min-height: 0;
}
.arena-column { min-width: 0; min-height: 0; display: flex; }
.arena-shell {
  position: relative; width: 100%; height: 100%; min-height: 0;
  border: 1px solid var(--line); border-radius: 10px; overflow: hidden;
  background: #050a11;
  box-shadow: inset 0 0 80px rgba(0,0,0,.55), 0 12px 40px rgba(0,0,0,.4);
}
#arena { width: 100%; height: 100%; }
.arena-grain {
  position: absolute; inset: 0; pointer-events: none; opacity: .22; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.35'/%3E%3C/svg%3E");
}
.arena-corners i {
  position: absolute; width: 18px; height: 18px; pointer-events: none;
  border-color: rgba(95, 227, 209, .35); border-style: solid; border-width: 0;
}
.arena-corners i:nth-child(1) { left: 8px; top: 8px; border-left-width: 1px; border-top-width: 1px; }
.arena-corners i:nth-child(2) { right: 8px; top: 8px; border-right-width: 1px; border-top-width: 1px; }
.arena-corners i:nth-child(3) { left: 8px; bottom: 8px; border-left-width: 1px; border-bottom-width: 1px; }
.arena-corners i:nth-child(4) { right: 8px; bottom: 8px; border-right-width: 1px; border-bottom-width: 1px; }

.phase-banner {
  position: absolute; top: 16px; left: 50%; transform: translate(-50%, -6px);
  padding: 5px 22px; border: 1px solid rgba(95,227,209,.2); border-radius: 3px;
  background: linear-gradient(90deg, transparent, rgba(5,12,18,.9) 18%, rgba(5,12,18,.9) 82%, transparent);
  font-family: var(--display); font-size: 11px; font-weight: 700; letter-spacing: .38em;
  color: var(--cyan); text-transform: uppercase; white-space: nowrap;
  opacity: 0; pointer-events: none; transition: opacity .4s, transform .4s;
  text-shadow: 0 0 18px rgba(95,227,209,.5);
}
.phase-banner.show { opacity: 1; transform: translate(-50%, 0); }
.phase-banner.foe { color: var(--red); text-shadow: 0 0 18px rgba(255,92,108,.5); border-color: rgba(255,92,108,.2); }
.phase-banner.gold { color: var(--gold); text-shadow: 0 0 18px rgba(240,200,121,.5); border-color: rgba(240,200,121,.25); }
.phase-banner small { display: block; text-align: center; font-family: var(--ui); font-size: 8px; letter-spacing: .22em; color: var(--muted); margin-top: 3px; }

.battle-timer {
  position: absolute; top: 12px; right: 14px; display: flex; align-items: baseline; gap: 6px;
  padding: 5px 10px; background: rgba(4, 9, 15, .72); border: 1px solid var(--line); border-radius: 4px;
  opacity: 0; pointer-events: none; transition: opacity .3s;
}
.battle-timer.show { opacity: 1; }
.bt-label { font-size: 7px; letter-spacing: .2em; color: var(--dim); }
.bt-value { font-size: 15px; font-weight: 600; color: var(--txt); font-variant-numeric: tabular-nums; }

.arena-hint {
  position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%);
  padding: 5px 14px; border-radius: 4px; border: 1px solid rgba(130,190,220,.12);
  background: rgba(5, 11, 18, .78); font-size: 10.5px; letter-spacing: .04em; color: var(--muted);
  white-space: nowrap; pointer-events: none; opacity: 0; transition: opacity .3s;
}
.arena-hint.show { opacity: 1; }
.arena-hint b { color: var(--cyan); font-weight: 700; }
.arena-hint .kbd { margin: 0 1px; }

.speed-controls {
  position: absolute; bottom: 10px; right: 12px; display: flex; gap: 2px;
  padding: 2px; background: rgba(4,9,15,.8); border: 1px solid var(--line); border-radius: 4px;
  opacity: 0; pointer-events: none; transition: opacity .3s;
}
.speed-controls.show { opacity: 1; pointer-events: auto; }
.speed-btn {
  min-width: 28px; height: 22px; padding: 0 5px; font-size: 10px; font-weight: 700; color: var(--muted);
  border-radius: 3px; transition: .15s;
}
.speed-btn:hover { color: var(--text); background: rgba(255,255,255,.05); }
.speed-btn.active { color: #07120f; background: var(--cyan); }

/* ══ SIDEBAR ═════════════════════════════════════════════════════════════════ */
.sidebar {
  min-height: 0; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; gap: 10px;
  padding-right: 2px; scrollbar-gutter: stable;
}
.panel {
  position: relative; padding: 13px 14px 12px; border: 1px solid var(--line); border-radius: 8px;
  background: linear-gradient(160deg, rgba(14, 27, 41, .88), rgba(7, 14, 22, .92));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.035);
}
.panel::before, .panel::after {
  content: ''; position: absolute; width: 9px; height: 9px; pointer-events: none;
  border-color: rgba(95,227,209,.25); border-style: solid;
}
.panel::before { left: -1px; top: -1px; border-width: 1px 0 0 1px; border-top-left-radius: 8px; }
.panel::after { right: -1px; bottom: -1px; border-width: 0 1px 1px 0; border-bottom-right-radius: 8px; }
.panel.boss-panel { border-color: rgba(255,92,108,.22); background: linear-gradient(160deg, rgba(40, 16, 22, .75), rgba(8, 13, 20, .92)); }
.panel.boss-panel::before, .panel.boss-panel::after { border-color: rgba(255,92,108,.35); }
.eyebrow {
  font-size: 8px; font-weight: 700; letter-spacing: .28em; color: var(--dim); text-transform: uppercase;
  display: flex; align-items: center; gap: 7px;
}
.eyebrow b { color: var(--gold); font-weight: 700; }
.eyebrow .dot { width: 4px; height: 4px; background: var(--dim); transform: rotate(45deg); }
h2.wave-name {
  font-family: var(--display); font-weight: 700; font-size: 19px; letter-spacing: .06em;
  color: #f2f8fd; margin: 4px 0 2px; line-height: 1.12;
}
.panel.boss-panel h2.wave-name { color: #ffdfe2; text-shadow: 0 0 22px rgba(255,92,108,.25); }
.wave-sub { font-size: 8.5px; letter-spacing: .16em; color: var(--dim); text-transform: uppercase; margin-bottom: 7px; }
.wave-desc { font-size: 11.5px; line-height: 1.45; color: var(--muted); font-weight: 500; }
.boss-tag {
  display: inline-flex; align-items: center; gap: 4px; margin-top: 6px; padding: 2px 7px;
  font-size: 8px; font-weight: 700; letter-spacing: .2em; color: #ffb3bb;
  border: 1px solid rgba(255,92,108,.35); background: rgba(255,92,108,.08); border-radius: 3px;
}
.intel-head {
  display: flex; align-items: center; justify-content: space-between;
  margin: 11px 0 6px; padding-top: 9px; border-top: 1px solid rgba(130,190,220,.09);
  font-size: 8px; font-weight: 700; letter-spacing: .2em; color: var(--dim);
}
.intel-head span { color: var(--red); font-weight: 600; letter-spacing: .1em; }
.enemy-list { display: flex; flex-direction: column; gap: 4px; }
.enemy-row {
  display: grid; grid-template-columns: 24px minmax(0,1fr) auto; align-items: center; gap: 7px;
  padding: 3px 0;
}
.lane-badge {
  width: 20px; height: 20px; display: grid; place-items: center; border-radius: 3px;
  border: 1px solid rgba(255,120,135,.24); background: rgba(255,92,108,.06);
  font-size: 8.5px; font-weight: 700; color: #ff9aa5; letter-spacing: .03em;
}
.lane-badge.you { border-color: rgba(95,227,209,.24); background: rgba(95,227,209,.06); color: var(--cyan); }
.enemy-row .er-main { min-width: 0; }
.er-name { font-size: 11px; font-weight: 600; color: #e9f2fa; letter-spacing: .03em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.er-meta { font-size: 8px; color: var(--dim); text-transform: uppercase; letter-spacing: .1em; margin-top: 0; display: flex; gap: 4px; align-items: center; }
.er-traits { display: flex; gap: 2px; }
.mini-trait {
  width: 14px; height: 14px; display: grid; place-items: center; border-radius: 2px;
  font-size: 8px; color: var(--tc, var(--muted));
  background: color-mix(in srgb, var(--tc, #8899aa) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--tc, #8899aa) 25%, transparent);
}
.tier-dots { display: flex; gap: 2px; }
.tier-dot { width: 4px; height: 4px; transform: rotate(45deg); background: rgba(240,200,121,.55); }
.tier-dot.off { background: rgba(255,255,255,.1); }

/* market */
.shop-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.shop-title { font-family: var(--display); font-size: 12px; font-weight: 700; letter-spacing: .14em; color: var(--gold-2); }
.shop-head small { font-size: 8px; letter-spacing: .14em; color: var(--dim); }
.shop-offers { display: flex; flex-direction: column; gap: 5px; }
.shop-card {
  display: grid; grid-template-columns: 38px minmax(0,1fr) auto; align-items: center; gap: 9px;
  padding: 5px 7px; border: 1px solid rgba(130,190,220,.1); border-radius: 5px;
  background: rgba(255,255,255,.018); transition: .18s;
}
.shop-card:hover { border-color: rgba(130,210,240,.24); background: rgba(95,227,209,.035); }
.shop-card.sold { opacity: .45; }
.shop-card canvas { width: 38px; height: 38px; }
.sc-main { min-width: 0; }
.sc-name { font-size: 11.5px; font-weight: 600; color: #eaf4fa; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sc-meta { font-size: 8px; letter-spacing: .1em; color: var(--dim); text-transform: uppercase; margin-top: 1px; }
.sc-traits { display: flex; gap: 2px; margin-top: 3px; }
.buy-btn {
  display: flex; align-items: center; gap: 4px; height: 25px; padding: 0 8px;
  border: 1px solid rgba(240,200,121,.26); border-radius: 4px;
  background: rgba(240,200,121,.07); color: var(--gold-2);
  font-size: 10.5px; font-weight: 700; letter-spacing: .05em; transition: .15s; white-space: nowrap;
}
.buy-btn:hover { background: rgba(240,200,121,.16); border-color: rgba(240,200,121,.5); }
.buy-btn:disabled { opacity: .35; cursor: default; }
.buy-btn .gem { width: 6px; height: 6px; transform: rotate(45deg); background: var(--gold); }
.shop-foot { display: flex; justify-content: space-between; align-items: center; margin-top: 7px; }
.reroll-btn { font-size: 9px; font-weight: 600; letter-spacing: .12em; color: var(--muted); padding: 3px 0; }
.reroll-btn:hover { color: var(--cyan); }
.reroll-btn:disabled { opacity: .35; cursor: default; }
.shop-foot small { font-size: 8px; color: var(--dim); letter-spacing: .06em; }

/* battle side */
.battle-side { display: flex; flex-direction: column; gap: 10px; min-height: 0; }
.bs-header { display: flex; align-items: center; justify-content: space-between; }
.bs-wave { font-family: var(--display); font-size: 13px; font-weight: 700; letter-spacing: .1em; color: #eaf4fa; }
.bs-timer { font-size: 11px; color: var(--gold); font-weight: 600; letter-spacing: .08em; }
.log-panel { flex: 1; min-height: 110px; display: flex; flex-direction: column; overflow: hidden; }
.log-title { font-size: 8px; letter-spacing: .24em; color: var(--dim); font-weight: 700; margin-bottom: 7px; display: flex; justify-content: space-between; }
.log-list { display: flex; flex-direction: column-reverse; gap: 5px; overflow-y: auto; max-height: 250px; padding-right: 2px; }
.log-line { display: flex; gap: 6px; align-items: baseline; font-size: 10px; line-height: 1.25; color: var(--muted); animation: logIn .25s; }
.log-line i { color: var(--tc, var(--cyan)); font-style: normal; font-size: 9px; flex: none; width: 10px; text-align: center; }
.log-line b { color: #e6f0f8; font-weight: 600; }
.log-line.cast i { color: var(--gold); }
.log-line.death i { color: var(--red); }
.log-line.breach i { color: var(--red); }
@keyframes logIn { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
.battle-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.bstat { padding: 6px 8px; border: 1px solid rgba(130,190,220,.1); border-radius: 4px; background: rgba(255,255,255,.018); }
.bstat small { font-size: 7px; letter-spacing: .15em; color: var(--dim); display: block; }
.bstat b { font-size: 15px; font-weight: 700; color: #e7f0f8; }
.auto-note {
  padding: 7px 9px; border: 1px solid rgba(240,200,121,.16); border-radius: 4px;
  background: rgba(240,200,121,.045); font-size: 9.5px; line-height: 1.35; color: rgba(240,214,150,.8);
}
.auto-note b { color: var(--gold-2); font-weight: 700; }

.battle-btn { width: 100%; height: 46px; font-size: 12.5px; }
.battle-btn .btn-sub { font-family: var(--ui); font-size: 8px; letter-spacing: .08em; opacity: .65; margin-left: 2px; }

.tip-box {
  padding: 8px 10px; border-left: 2px solid rgba(95,227,209,.35); background: rgba(95,227,209,.035);
  font-size: 10px; line-height: 1.45; color: var(--muted);
}
.tip-box b { color: var(--cyan); font-weight: 600; }
.deploy-count { display: flex; align-items: center; justify-content: space-between; font-size: 9px; color: var(--dim); letter-spacing: .08em; }
.deploy-count b { color: var(--cyan); font-size: 11px; }
.empty-note { padding: 12px; text-align: center; font-size: 10px; color: var(--dim); }

/* ══ BUTTONS ═════════════════════════════════════════════════════════════════ */
.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  height: 40px; padding: 0 18px; border: 1px solid var(--line-strong); border-radius: 5px;
  background: rgba(255,255,255,.035); color: #e8f2f9;
  font-family: var(--ui); font-weight: 700; font-size: 11px; letter-spacing: .16em; text-transform: uppercase;
  transition: .18s; overflow: hidden; white-space: nowrap;
}
.btn::before {
  content: ''; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 20%, rgba(255,255,255,.12) 50%, transparent 80%);
  transform: translateX(-120%); transition: transform .5s;
}
.btn:hover::before { transform: translateX(120%); }
.btn:hover { border-color: rgba(150,225,245,.4); background: rgba(255,255,255,.06); transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn:disabled { opacity: .38; pointer-events: none; }
.btn-primary {
  background: linear-gradient(135deg, #8af3e2 0%, #4fd8c6 45%, #2aa99d 100%);
  color: #041512; border-color: rgba(160,255,240,.6);
  box-shadow: 0 4px 24px rgba(69, 216, 197, .22), inset 0 1px 0 rgba(255,255,255,.4);
}
.btn-primary:hover { background: linear-gradient(135deg, #a5f8ea, #5ce5d2 45%, #30bbae); box-shadow: 0 6px 30px rgba(69,216,197,.35); }
.btn-gold {
  background: linear-gradient(135deg, #ffe6a3 0%, #efc270 45%, #c9943b 100%);
  color: #1c1203; border-color: rgba(255,232,170,.55);
  box-shadow: 0 4px 24px rgba(240, 200, 121, .2), inset 0 1px 0 rgba(255,255,255,.4);
}
.btn-gold:hover { background: linear-gradient(135deg, #fff0c0, #f6cf85 45%, #d9a44c); }
.btn-ghost { background: rgba(10,20,30,.5); }
.btn-sm { height: 28px; padding: 0 10px; font-size: 9px; letter-spacing: .1em; }
.btn-lg { height: 52px; padding: 0 30px; font-size: 13px; letter-spacing: .22em; }
.btn .btn-arrow { font-size: 18px; margin-left: 4px; opacity: .7; }
.btn .kbd { margin-left: 4px; }
.btn-primary .kbd { border-color: rgba(0,30,25,.3); color: rgba(0,25,20,.65); background: rgba(255,255,255,.2); }

.kbd {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px;
  border: 1px solid rgba(160,210,235,.24); border-radius: 3px;
  background: rgba(5,12,18,.5); font-family: var(--ui); font-size: 8px; font-weight: 700;
  color: var(--muted); letter-spacing: .02em;
}

.btn-splice { color: var(--cyan); border-color: rgba(95,227,209,.28); background: rgba(95,227,209,.055); }
.btn-splice:hover { background: rgba(95,227,209,.12); }

/* ══ DOCK / BENCH ════════════════════════════════════════════════════════════ */
.dock {
  border-top: 1px solid var(--line); background: linear-gradient(180deg, rgba(9,19,29,.92), rgba(5,10,16,.97));
  padding: 8px 16px 10px; display: flex; flex-direction: column; min-height: 0; position: relative; z-index: 15;
}
.dock::before {
  content: ''; position: absolute; left: 0; right: 0; top: -1px; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(95,227,209,.35), rgba(240,200,121,.2), transparent);
  opacity: .45;
}
.dock-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; height: 30px; flex: none; }
.dock-title { display: flex; align-items: baseline; gap: 10px; }
.dock-title h3 {
  font-family: var(--display); font-size: 11px; font-weight: 700; letter-spacing: .2em; color: #dfeaf3;
}
.dock-title .count { font-size: 9px; color: var(--dim); letter-spacing: .1em; }
.dock-title .count b { color: var(--cyan); }
.dock-title .dock-tip { font-size: 9px; color: var(--dim); letter-spacing: .04em; margin-left: 5px; }
.dock-actions { display: flex; align-items: center; gap: 8px; }
.dock-body {
  flex: 1; min-height: 0; display: flex; gap: 7px; overflow-x: auto; overflow-y: hidden;
  padding: 2px 1px 4px; align-items: stretch;
}

.unit-card {
  position: relative; width: 107px; min-width: 107px; height: 100%;
  display: flex; flex-direction: column; align-items: center;
  padding: 5px 6px 5px; border: 1px solid rgba(130,190,220,.13); border-radius: 6px;
  background: linear-gradient(170deg, rgba(19, 35, 50, .9), rgba(7, 14, 22, .92));
  cursor: pointer; transition: transform .16s, border-color .16s, box-shadow .16s;
  overflow: hidden;
}
.unit-card::after {
  content: ''; position: absolute; left: 10%; right: 10%; bottom: 0; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(95,227,209,.4), transparent); opacity: 0; transition: .16s;
}
.unit-card:hover { transform: translateY(-3px); border-color: rgba(130,210,240,.32); box-shadow: 0 8px 22px rgba(0,0,0,.35); }
.unit-card:hover::after { opacity: 1; }
.unit-card[data-tier="2"] { border-color: rgba(95,227,209,.2); }
.unit-card[data-tier="3"] { border-color: rgba(240,200,121,.28); }
.unit-card[data-tier="4"] { border-color: rgba(180,150,255,.4); box-shadow: inset 0 0 22px rgba(160,120,255,.08); }
.unit-card.selected { border-color: rgba(95,227,209,.75); box-shadow: 0 0 0 1px rgba(95,227,209,.25), 0 0 24px rgba(95,227,209,.18); transform: translateY(-3px); }
.unit-card.selected::after { opacity: 1; }
.unit-card.deployed { background: linear-gradient(170deg, rgba(20, 40, 52, .92), rgba(8, 16, 24, .94)); }
.uc-top { width: 100%; display: flex; justify-content: space-between; align-items: flex-start; height: 10px; }
.uc-tier { display: flex; gap: 2px; padding-top: 1px; }
.uc-tier i { width: 4.5px; height: 4.5px; transform: rotate(45deg); background: rgba(95,227,209,.6); }
.unit-card[data-tier="3"] .uc-tier i { background: var(--gold); }
.unit-card[data-tier="4"] .uc-tier i { background: var(--violet); }
.uc-deploy {
  font-size: 7px; font-weight: 700; letter-spacing: .05em; color: var(--cyan);
  padding: 1px 4px; border: 1px solid rgba(95,227,209,.28); border-radius: 2px;
  background: rgba(95,227,209,.07); display: none;
}
.unit-card.deployed .uc-deploy { display: block; }
.uc-art { width: 58px; height: 58px; margin: -2px 0 -1px; pointer-events: none; filter: drop-shadow(0 4px 8px rgba(0,0,0,.4)); }
.uc-name {
  font-size: 10.5px; font-weight: 700; letter-spacing: .05em; color: #ecf5fb;
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; line-height: 1.1;
}
.uc-line {
  font-size: 7px; color: var(--dim); letter-spacing: .1em; text-transform: uppercase;
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin-top: 1px;
}
.uc-traits { display: flex; gap: 2px; margin-top: 3px; height: 15px; align-items: center; }
.uc-bottom { width: 100%; display: flex; justify-content: space-between; margin-top: auto; padding-top: 2px; border-top: 1px solid rgba(130,190,220,.07); }
.uc-stat { display: flex; align-items: baseline; gap: 2px; font-size: 7px; color: var(--dim); letter-spacing: .05em; }
.uc-stat b { font-size: 10px; font-weight: 600; color: #dbe8f2; }

.ability-chip {
  position: relative; width: 128px; min-width: 128px; height: 100%;
  display: flex; flex-direction: column; align-items: center; padding: 4px 7px 5px;
  border: 1px solid rgba(130,190,220,.13); border-radius: 6px;
  background: linear-gradient(170deg, rgba(18, 32, 46, .92), rgba(7, 14, 22, .94));
  text-align: center; transition: .16s; overflow: hidden;
}
.ability-chip .ac-key {
  position: absolute; top: 4px; left: 5px; width: 15px; height: 15px; display: grid; place-items: center;
  border: 1px solid rgba(140,200,225,.2); border-radius: 2px; font-size: 8px; color: var(--muted);
  background: rgba(0,0,0,.25); font-weight: 700;
}
.ability-chip .ac-lane {
  position: absolute; top: 5px; right: 6px; font-size: 7px; letter-spacing: .08em; color: var(--dim); font-weight: 600;
}
.ability-chip canvas { width: 54px; height: 54px; margin: 1px 0 0; filter: drop-shadow(0 3px 6px rgba(0,0,0,.4)); }
.ability-chip .ac-name { font-size: 10px; font-weight: 700; letter-spacing: .03em; color: #eaf4fa; max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ability-chip .ac-skill { font-size: 7.5px; color: var(--dim); letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.ability-chip .ac-charge { width: 100%; height: 3px; margin-top: auto; background: rgba(0,0,0,.5); border-radius: 2px; overflow: hidden; }
.ability-chip .ac-charge i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #2b8e86, #5fe3d1); transition: width .2s linear; }
.ability-chip .ac-state { font-size: 7px; letter-spacing: .14em; color: var(--dim); margin-top: 3px; height: 9px; font-weight: 600; }
.ability-chip.ready { border-color: rgba(240,200,121,.65); box-shadow: 0 0 22px rgba(240,200,121,.16), inset 0 0 16px rgba(240,200,121,.06); cursor: pointer; }
.ability-chip.ready .ac-charge i { background: linear-gradient(90deg, #e2ab4f, #ffe6a3); box-shadow: 0 0 8px rgba(240,200,121,.6); }
.ability-chip.ready .ac-state { color: var(--gold-2); text-shadow: 0 0 10px rgba(240,200,121,.5); animation: readyPulse 1.4s infinite; }
.ability-chip.ready:hover { transform: translateY(-3px); }
.ability-chip.dead { opacity: .32; filter: grayscale(.8); }
.ability-chip.stunned { border-color: rgba(255,209,120,.18); }
.ability-chip .ac-tier { position: absolute; bottom: 16px; right: 7px; display: flex; gap: 1px; }
.ability-chip .ac-tier i { width: 3px; height: 3px; transform: rotate(45deg); background: rgba(240,200,121,.55); }
@keyframes readyPulse { 0%,100% { opacity: .75; } 50% { opacity: 1; } }

/* ══ TITLE ═══════════════════════════════════════════════════════════════════ */
.title-screen { position: fixed; inset: 0; z-index: 60; background: #04070d; overflow: hidden; transition: opacity .5s, visibility .5s; }
.title-screen.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
#titleCanvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.title-vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at 50% 45%, transparent 30%, rgba(2,5,9,.6) 100%); }
.title-ui {
  position: relative; z-index: 2; height: 100%; display: flex; flex-direction: column; align-items: center;
  padding: clamp(34px, 8vh, 92px) 24px 0; text-align: center; pointer-events: none;
}
.title-ui > * { pointer-events: auto; }
.title-kicker {
  display: flex; align-items: center; gap: 12px; font-size: 9px; font-weight: 700;
  letter-spacing: .38em; color: var(--dim); text-transform: uppercase;
  animation: riseIn .8s .1s both;
}
.title-kicker span { width: 42px; height: 1px; background: linear-gradient(90deg, transparent, rgba(95,227,209,.5)); }
.title-kicker span:last-child { background: linear-gradient(90deg, rgba(95,227,209,.5), transparent); }
.game-logo {
  margin-top: 12px; font-family: var(--display); font-weight: 900;
  font-size: clamp(44px, 7.2vw, 88px); line-height: .98; letter-spacing: .1em;
  color: #f2f9ff; text-shadow: 0 0 60px rgba(95,227,209,.22), 0 6px 30px rgba(0,0,0,.8);
  animation: logoIn 1s .2s both;
}
.game-logo span {
  display: inline-block; margin-left: .14em; color: transparent;
  background: linear-gradient(180deg, #b6fff5 0%, #5fe3d1 48%, #1f9a90 100%);
  -webkit-background-clip: text; background-clip: text;
  filter: drop-shadow(0 0 28px rgba(95,227,209,.45)) drop-shadow(0 2px 0 rgba(0,0,0,.4));
}
@keyframes logoIn { from { opacity: 0; transform: translateY(18px) scale(.98); filter: blur(6px); } to { opacity: 1; transform: none; filter: none; } }
@keyframes riseIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
.title-tag {
  margin-top: 14px; font-size: clamp(11px, 1.3vw, 15px); font-weight: 500; letter-spacing: .3em;
  color: #9bb2c7; text-transform: uppercase; animation: riseIn .8s .45s both;
}
.title-cta { display: flex; align-items: center; gap: 12px; margin-top: clamp(22px, 4vh, 40px); animation: riseIn .8s .6s both; }
.title-meta {
  display: flex; align-items: center; gap: 12px; margin-top: clamp(16px, 3vh, 28px);
  font-size: 8px; letter-spacing: .18em; color: rgba(130,155,180,.65); font-weight: 600;
  animation: riseIn .8s .75s both;
}
.title-meta b { color: var(--gold); font-weight: 700; }
.title-meta i { width: 3px; height: 3px; transform: rotate(45deg); background: rgba(130,155,180,.3); }
.title-version {
  position: absolute; bottom: 16px; left: 0; right: 0; text-align: center; z-index: 2;
  font-size: 7px; letter-spacing: .3em; color: rgba(110,135,160,.45);
}
@keyframes titleFade { to { opacity: 0; } }

/* ══ MODALS ══════════════════════════════════════════════════════════════════ */
.modal-root { position: fixed; inset: 0; z-index: 100; display: none; align-items: center; justify-content: center; padding: 20px; }
.modal-root.open { display: flex; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(2, 5, 9, .76); backdrop-filter: blur(6px); animation: fadeIn .2s; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.modal {
  position: relative; z-index: 1; width: min(960px, 96vw); max-height: 92vh;
  display: flex; flex-direction: column; border: 1px solid var(--line-strong); border-radius: 10px;
  background: linear-gradient(160deg, #0c1824, #071018 70%, #050b12);
  box-shadow: 0 40px 120px rgba(0,0,0,.7), inset 0 1px 0 rgba(255,255,255,.05);
  animation: modalIn .28s cubic-bezier(.2,.9,.3,1);
  overflow: hidden;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(16px) scale(.985); } to { opacity: 1; transform: none; } }
.modal::before {
  content: ''; position: absolute; left: 0; right: 0; top: 0; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(95,227,209,.6), rgba(240,200,121,.35), transparent);
}
.modal-head {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 20px;
  padding: 18px 22px 14px; border-bottom: 1px solid var(--line); flex: none;
}
.modal-head h2 { font-family: var(--display); font-size: 20px; letter-spacing: .1em; color: #eef7fc; font-weight: 700; }
.modal-head p { font-size: 10.5px; color: var(--muted); margin-top: 3px; letter-spacing: .03em; }
.modal-close {
  width: 30px; height: 30px; border: 1px solid var(--line); border-radius: 5px; color: var(--muted);
  font-size: 16px; display: grid; place-items: center; flex: none;
}
.modal-close:hover { color: var(--red); border-color: rgba(255,92,108,.35); background: rgba(255,92,108,.06); }
.modal-body { padding: 16px 22px; overflow-y: auto; min-height: 0; }
.modal-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  padding: 12px 22px; border-top: 1px solid var(--line); flex: none; background: rgba(0,0,0,.18);
}
.modal-foot .foot-note { font-size: 9.5px; color: var(--dim); letter-spacing: .03em; }
.modal-foot .foot-note b { color: var(--gold); }
.modal-foot .foot-actions { display: flex; gap: 8px; }

/* splice */
.splice-modal { width: min(1060px, 96vw); }
.splice-grid { display: grid; grid-template-columns: 280px minmax(0, 1fr) 272px; gap: 16px; min-height: 0; }
.splice-col { min-width: 0; }
.col-label { font-size: 8px; font-weight: 700; letter-spacing: .24em; color: var(--dim); text-transform: uppercase; margin-bottom: 8px; display: flex; justify-content: space-between; }
.col-label span { color: var(--muted); letter-spacing: .08em; }
.splice-roster { display: flex; flex-direction: column; gap: 5px; max-height: 435px; overflow-y: auto; padding-right: 3px; }
.splice-pick {
  display: grid; grid-template-columns: 44px 1fr auto; gap: 8px; align-items: center;
  padding: 4px 8px 4px 4px; border: 1px solid rgba(130,190,220,.12); border-radius: 5px;
  background: rgba(255,255,255,.018); cursor: pointer; transition: .15s; text-align: left;
}
.splice-pick:hover { border-color: rgba(130,210,240,.3); background: rgba(95,227,209,.04); }
.splice-pick.picked-a { border-color: rgba(95,227,209,.55); background: rgba(95,227,209,.07); }
.splice-pick.picked-b { border-color: rgba(180,150,255,.5); background: rgba(150,120,255,.07); }
.splice-pick canvas { width: 44px; height: 44px; }
.splice-pick .sp-main { min-width: 0; }
.splice-pick .sp-name { font-size: 10.5px; font-weight: 600; color: #eaf4fa; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.splice-pick .sp-meta { font-size: 7.5px; letter-spacing: .08em; color: var(--dim); text-transform: uppercase; }
.pick-badge {
  width: 18px; height: 18px; display: grid; place-items: center; border-radius: 3px;
  border: 1px solid rgba(140,190,215,.2); font-size: 8px; font-weight: 700; color: var(--dim);
}
.picked-a .pick-badge { background: var(--cyan); color: #041512; border-color: var(--cyan); }
.picked-b .pick-badge { background: var(--violet); color: #120a22; border-color: var(--violet); }
.splice-preview {
  border: 1px solid var(--line); border-radius: 8px; background:
    radial-gradient(ellipse at 50% 30%, rgba(95,227,209,.09), transparent 60%),
    linear-gradient(170deg, rgba(16,32,45,.7), rgba(6,12,19,.9));
  padding: 10px 14px 14px; display: flex; flex-direction: column; align-items: center; min-height: 435px;
  position: relative; overflow: hidden;
}
.splice-preview::before {
  content: ''; position: absolute; width: 280px; height: 280px; border: 1px solid rgba(95,227,209,.08);
  border-radius: 50%; top: 20px; left: 50%; transform: translateX(-50%);
  box-shadow: 0 0 0 26px rgba(95,227,209,.025), 0 0 0 54px rgba(95,227,209,.018);
  pointer-events: none;
}
.sp-art { width: 230px; height: 220px; margin-top: 0; position: relative; z-index: 1; }
.sp-name { font-family: var(--display); font-size: 21px; color: #f0f7fc; letter-spacing: .06em; font-weight: 700; text-align: center; line-height: 1.15; position: relative; z-index: 1; }
.sp-lineage { font-size: 8px; letter-spacing: .16em; color: var(--cyan); text-transform: uppercase; margin-top: 3px; font-weight: 600; }
.sp-role { font-size: 8px; letter-spacing: .16em; color: var(--dim); text-transform: uppercase; margin-top: 2px; }
.sp-traits { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px; margin-top: 9px; position: relative; z-index: 1; }
.sp-stats { width: 100%; display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; margin-top: 12px; position: relative; z-index: 1; }
.sp-stat { text-align: center; padding: 5px 2px; border: 1px solid rgba(130,190,220,.1); border-radius: 3px; background: rgba(0,0,0,.18); }
.sp-stat small { display: block; font-size: 6.5px; letter-spacing: .14em; color: var(--dim); }
.sp-stat b { font-size: 14px; color: #e8f2f9; font-weight: 600; }
.sp-stat i { display: block; font-style: normal; font-size: 7px; color: var(--green); margin-top: 1px; }
.sp-stat i.down { color: var(--red); }
.sp-ability { width: 100%; margin-top: 8px; padding: 7px 9px; border: 1px solid rgba(240,200,121,.17); background: rgba(240,200,121,.035); border-radius: 4px; position: relative; z-index: 1; }
.sp-ability b { font-size: 10px; color: var(--gold-2); letter-spacing: .04em; }
.sp-ability span { display: block; font-size: 9px; color: var(--muted); margin-top: 2px; line-height: 1.3; }
.splice-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; min-height: 380px; color: var(--dim); text-align: center; }
.splice-empty .se-rune {
  width: 76px; height: 76px; transform: rotate(45deg); border: 1px solid rgba(95,227,209,.2);
  display: grid; place-items: center; margin-bottom: 22px;
}
.splice-empty .se-rune span { transform: rotate(-45deg); font-family: var(--display); font-size: 26px; color: rgba(95,227,209,.5); }
.splice-empty h3 { font-family: var(--display); font-size: 15px; letter-spacing: .12em; color: var(--muted); margin-bottom: 6px; }
.splice-empty p { font-size: 10px; max-width: 260px; line-height: 1.5; }

.splice-out { display: flex; flex-direction: column; gap: 8px; }
.out-box { padding: 9px 10px; border: 1px solid rgba(130,190,220,.11); border-radius: 5px; background: rgba(255,255,255,.018); }
.out-box .ob-label { font-size: 7px; letter-spacing: .18em; color: var(--dim); text-transform: uppercase; }
.out-box .ob-main { font-size: 12px; font-weight: 600; color: #e9f3fa; margin-top: 1px; }
.out-box .ob-sub { font-size: 8.5px; color: var(--dim); margin-top: 2px; line-height: 1.4; }
.out-box .ob-sub b { color: var(--cyan); font-weight: 600; }
.parent-row { display: flex; align-items: center; gap: 6px; padding: 4px 0; }
.parent-row canvas { width: 32px; height: 32px; }
.parent-row .pr-name { font-size: 10.5px; font-weight: 600; color: #e6f0f8; }
.parent-row .pr-tag { font-size: 7px; letter-spacing: .1em; color: var(--dim); text-transform: uppercase; }
.swap-btn { width: 100%; margin-top: 2px; }
.cost-row { display: flex; align-items: center; justify-content: space-between; padding: 9px 10px; border: 1px solid rgba(240,200,121,.2); border-radius: 5px; background: rgba(240,200,121,.045); }
.cost-row span { font-size: 8px; letter-spacing: .18em; color: var(--dim); }
.cost-row b { font-size: 17px; color: var(--gold-2); font-weight: 700; display: flex; align-items: center; gap: 6px; }
.cost-row b .gem { width: 9px; height: 9px; transform: rotate(45deg); background: var(--gold); }
.cost-row b.insufficient { color: var(--red); }
.splice-warn { font-size: 9px; color: #ffb3ba; letter-spacing: .04em; padding: 2px 1px; }
.splice-hint { font-size: 8.5px; color: var(--dim); line-height: 1.45; }

/* help */
.help-modal { width: min(760px, 96vw); }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.help-step { display: grid; grid-template-columns: 26px 1fr; gap: 9px; padding: 10px; border: 1px solid rgba(130,190,220,.1); border-radius: 6px; background: rgba(255,255,255,.018); }
.help-step .hs-num { width: 24px; height: 24px; border: 1px solid rgba(95,227,209,.3); color: var(--cyan); display: grid; place-items: center; font-family: var(--display); font-size: 11px; transform: rotate(45deg); }
.help-step .hs-num span { transform: rotate(-45deg); }
.help-step h4 { font-size: 11.5px; font-weight: 700; letter-spacing: .05em; color: #e8f2f9; margin-bottom: 2px; }
.help-step p { font-size: 10px; line-height: 1.5; color: var(--muted); }
.help-step p b { color: var(--cyan); font-weight: 600; }
.help-traits { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--line); }
.help-traits h4 { font-family: var(--display); font-size: 12px; letter-spacing: .12em; color: var(--gold-2); margin-bottom: 8px; }
.trait-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 14px; }
.trait-detail { display: flex; gap: 7px; align-items: baseline; font-size: 9px; color: var(--muted); line-height: 1.3; }
.trait-detail .td-icon { width: 15px; flex: none; text-align: center; color: var(--tc); font-size: 10px; }
.trait-detail b { color: #dfeaf3; font-weight: 600; }

/* result */
.result-modal { width: min(560px, 94vw); text-align: center; }
.result-modal .modal-body { padding: 26px 30px 22px; }
.result-emblem { width: 72px; height: 72px; margin: 0 auto 12px; transform: rotate(45deg); border: 1px solid rgba(240,200,121,.4); display: grid; place-items: center; background: rgba(240,200,121,.05); box-shadow: 0 0 40px rgba(240,200,121,.15) inset; }
.result-emblem span { transform: rotate(-45deg); font-family: var(--display); font-size: 24px; color: var(--gold); }
.result-modal.loss .result-emblem { border-color: rgba(255,92,108,.4); background: rgba(255,92,108,.05); box-shadow: 0 0 40px rgba(255,92,108,.12) inset; }
.result-modal.loss .result-emblem span { color: var(--red); }
.result-kicker { font-size: 8px; letter-spacing: .36em; color: var(--dim); font-weight: 700; }
.result-title { font-family: var(--display); font-size: 34px; letter-spacing: .08em; font-weight: 700; color: #f6fbfe; margin-top: 4px; text-shadow: 0 0 40px rgba(240,200,121,.2); }
.result-modal.loss .result-title { color: #ffe3e6; text-shadow: 0 0 40px rgba(255,92,108,.25); }
.result-sub { font-size: 11px; color: var(--muted); letter-spacing: .06em; margin-top: 5px; line-height: 1.4; }
.result-reward { display: flex; align-items: center; justify-content: center; gap: 8px; margin: 16px auto 4px; padding: 7px 16px; border: 1px solid rgba(240,200,121,.25); border-radius: 4px; background: rgba(240,200,121,.06); width: fit-content; font-size: 12px; color: var(--gold-2); font-weight: 600; letter-spacing: .06em; }
.result-reward .gem { width: 9px; height: 9px; transform: rotate(45deg); background: var(--gold); }
.result-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 16px; }
.result-stats .rs { padding: 8px 6px; border: 1px solid rgba(130,190,220,.1); border-radius: 4px; background: rgba(0,0,0,.15); }
.result-stats small { display: block; font-size: 7px; letter-spacing: .16em; color: var(--dim); }
.result-stats b { font-size: 17px; color: #e9f3fa; font-weight: 600; }
.result-actions { display: flex; gap: 9px; justify-content: center; margin-top: 20px; }

/* ══ TOASTS & TOOLTIP ═══════════════════════════════════════════════════════ */
.toasts { position: fixed; top: calc(var(--top-h) + 10px); left: 50%; transform: translateX(-50%); z-index: 120; display: flex; flex-direction: column; gap: 6px; align-items: center; pointer-events: none; }
.toast {
  padding: 6px 14px; border: 1px solid rgba(130,200,230,.2); border-radius: 4px;
  background: rgba(6, 14, 21, .92); color: #dbeaf5; font-size: 10px; font-weight: 600;
  letter-spacing: .08em; box-shadow: 0 8px 30px rgba(0,0,0,.4);
  animation: toastIn .25s, toastOut .3s 2.5s forwards; white-space: nowrap; max-width: 80vw;
  overflow: hidden; text-overflow: ellipsis;
}
.toast.good { border-color: rgba(95,227,209,.35); color: #b9fff4; }
.toast.error { border-color: rgba(255,92,108,.4); color: #ffc2c8; }
.toast.epic { border-color: rgba(240,200,121,.4); color: #ffe6ae; background: rgba(18, 14, 7, .94); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-4px); } }

.tooltip {
  position: fixed; z-index: 200; max-width: 260px; padding: 8px 10px;
  border: 1px solid rgba(130,200,230,.22); border-radius: 5px;
  background: rgba(6, 14, 22, .97); box-shadow: 0 12px 40px rgba(0,0,0,.55);
  opacity: 0; pointer-events: none; transform: translateY(4px); transition: opacity .12s, transform .12s;
}
.tooltip.show { opacity: 1; transform: none; }
.tooltip b { display: block; font-size: 10.5px; color: #eaf4fa; letter-spacing: .04em; }
.tooltip span { display: block; font-size: 9.5px; line-height: 1.4; color: var(--muted); margin-top: 2px; }
.tooltip .tt-meta { color: var(--dim); font-size: 8px; letter-spacing: .1em; text-transform: uppercase; margin-top: 4px; }

/* ══ RESPONSIVE ══════════════════════════════════════════════════════════════ */
@media (max-width: 1220px) {
  :root { --side-w: 300px; }
  .brand { min-width: 205px; }
  .brand-text h1 { font-size: 15px; }
  .brand-text span { letter-spacing: .24em; }
  .nexus-pair { display: none; }
}
@media (max-width: 1040px) {
  :root { --dock-h: 158px; --side-w: 282px; }
  .wave-progress { gap: 8px; }
  .wp-pips { gap: 3px; }
  .wp-pip { width: 12px; height: 12px; }
  .wp-pip::before { width: 6px; height: 6px; }
  .brand-text span { display: none; }
  .brand { min-width: 180px; }
  .unit-card { width: 98px; min-width: 98px; }
  .ability-chip { width: 112px; min-width: 112px; }
  .uc-art { width: 52px; height: 52px; }
  .dock-title .dock-tip { display: none; }
}
@media (max-width: 900px) {
  body { overflow: auto; }
  .app { height: auto; min-height: 100dvh; grid-template-rows: var(--top-h) auto auto; }
  .main { grid-template-columns: 1fr; grid-template-rows: minmax(360px, 56vh) auto; }
  .sidebar { max-height: none; overflow: visible; display: grid; grid-template-columns: 1fr 1fr; align-items: start; }
  .sidebar .battle-btn, .sidebar .tip-box, .sidebar .deploy-count { grid-column: 1 / -1; }
  .dock { height: auto; min-height: 150px; }
  .dock-body { min-height: 128px; }
  .title-meta { display: none; }
  .splice-grid { grid-template-columns: 240px 1fr; }
  .splice-col.out { grid-column: 1 / -1; }
  .splice-out { display: grid; grid-template-columns: 1fr 1fr; align-items: start; }
  .help-grid { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  :root { --top-h: 56px; --dock-h: 152px; }
  .topbar { gap: 10px; padding: 0 10px; }
  .brand-text h1 { font-size: 13px; letter-spacing: .1em; }
  .brand { min-width: 140px; }
  .brand-mark { width: 26px; height: 26px; }
  .wave-progress { display: none; }
  .top-resources { margin-left: auto; }
  .main { padding: 8px; gap: 8px; }
  .sidebar { grid-template-columns: 1fr; }
  .game-logo { font-size: clamp(34px, 11vw, 56px); }
  .title-tag { letter-spacing: .16em; font-size: 10px; padding: 0 12px; }
  .title-cta { flex-direction: column; width: 100%; padding: 0 20px; }
  .title-cta .btn { width: 100%; }
  .splice-grid { grid-template-columns: 1fr; }
  .splice-preview { min-height: 360px; }
  .trait-grid { grid-template-columns: 1fr; }
  .result-stats { grid-template-columns: 1fr 1fr; }
  .dock-title h3 { font-size: 9px; }
  .modal-body { padding: 12px; }
  .modal-head { padding: 14px; }
  .modal-foot { padding: 10px 14px; flex-direction: column; align-items: stretch; }
  .foot-actions { justify-content: flex-end; }
}
@media (max-height: 760px) {
  :root { --dock-h: 150px; --top-h: 58px; }
  .uc-art { width: 48px; height: 48px; }
  .unit-card { width: 100px; min-width: 100px; }
  .uc-line { display: none; }
  .uc-traits { margin-top: 2px; }
  .sidebar { gap: 8px; }
  .panel { padding: 10px 12px; }
  .wave-desc { font-size: 10.5px; }
  .title-ui { padding-top: 26px; }
  .game-logo { font-size: clamp(40px, 6vw, 66px); }
  .title-cta { margin-top: 18px; }
  .title-meta { margin-top: 12px; }
}

