import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
page.setDefaultTimeout(15000)
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
page.on('console', m => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()) } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.waitForTimeout(700)

const shot = async (name) => { await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 82 }) }
const state = () => page.evaluate(() => {
  const S = window.__CHIMERA.S
  return {
    screen: S.screen, phase: S.phase, wave: S.wave, essence: S.essence,
    roster: S.roster.map(u => ({ name: u.name, lane: u.lane, row: u.row, tier: u.tier, id: u.id, hp: u.maxHp })),
    slots: Object.keys(S.slots).length, shop: S.shop.map(u => u && u.name),
    enemy: S.enemyPreview.map(e => ({ name: e.unit.name, lane: e.lane, row: e.row, tier: e.unit.tier })),
    battle: S.battle ? { time: S.battle.time, over: S.battle.over, winner: S.battle.winner, nexus: S.battle.nexus.map(n => ({ side: n.side, hp: n.hp })), units: S.battle.units.length } : null,
  }
})

const step = process.argv[2] || 'inspect'
console.log('STATE', JSON.stringify(await state(), null, 1))

if (step === 'start') {
  await page.click('#titleScreen .title-start, #startBtn, .btn-primary')
  await page.waitForTimeout(800)
  console.log('AFTER START', JSON.stringify(await state(), null, 1))
  await shot('prep-live')
}

if (step === 'deploy') {
  // start game if on title
  const scr = await page.evaluate(() => window.__CHIMERA.S.screen)
  if (scr === 'title') { await page.click('#startBtn, .title-start'); await page.waitForTimeout(700) }
  // deploy two cheapest roster to lanes 2 and 4 by clicking roster then slot
  const info = await page.evaluate(() => {
    const S = window.__CHIMERA.S
    const av = window.__CHIMERA.arena
    return { roster: S.roster.map(u => ({ id: u.id, name: u.name })), view: av.view }
  })
  console.log('DEPLOY INFO', JSON.stringify(info))
  await page.evaluate(() => {
    const S = window.__CHIMERA.S
    // place first roster unit in lane 2 front
    const u = S.roster[0]
    if (u) { u.lane = 2; u.row = 'front'; S.slots['2-front'] = u.id; S.selectedId = u.id }
  })
  await page.evaluate(() => window.__CHIMERA.renderAll())
  await page.waitForTimeout(500)
  await shot('deploy-1')
  console.log('AFTER DEPLOY', JSON.stringify(await state(), null, 1))
}

if (step === 'battle') {
  const scr = await page.evaluate(() => window.__CHIMERA.S.screen)
  if (scr === 'title') { await page.click('#startBtn, .title-start'); await page.waitForTimeout(700) }
  await page.evaluate(() => {
    const S = window.__CHIMERA.S
    const lanes = [0, 1, 2, 3, 4]
    S.roster.forEach((u, i) => { u.lane = lanes[i % 5]; u.row = i < 5 ? 'front' : 'back'; S.slots[`${u.lane}-${u.row}`] = u.id })
    window.__CHIMERA.renderAll()
  })
  await page.waitForTimeout(300)
  await page.evaluate(() => window.__CHIMERA.startBattle())
  await page.waitForTimeout(4500)
  console.log('BATTLE', JSON.stringify(await state(), null, 1))
  await shot('battle-1')
  await page.waitForTimeout(6000)
  console.log('BATTLE2', JSON.stringify(await state(), null, 1))
  await shot('battle-2')
}

if (step === 'full') {
  const scr = await page.evaluate(() => window.__CHIMERA.S.screen)
  if (scr === 'title') { await page.click('#startBtn, .title-start'); await page.waitForTimeout(700) }
  for (let w = 0; w < 3; w++) {
    const st = await state()
    console.log('WAVE', st.wave, 'essence', st.essence, 'roster', st.roster.map(r => r.name))
    await page.evaluate(() => {
      const S = window.__CHIMERA.S
      S.roster.forEach((u, i) => { u.lane = i % 5; u.row = i < 5 ? 'front' : 'back'; S.slots[`${u.lane}-${u.row}`] = u.id })
      window.__CHIMERA.renderAll()
    })
    await page.waitForTimeout(200)
    await page.evaluate(() => window.__CHIMERA.startBattle())
    await page.waitForTimeout(12000)
    console.log('AFTER', JSON.stringify(await state()))
    await shot(`auto-wave-${w + 1}`)
    // dismiss results if present
    const btn = await page.$('#modalRoot .btn-primary')
    if (btn) { await btn.click(); await page.waitForTimeout(900) }
  }
}

console.log('ERRORS', errors.length)
await browser.close()

