export function uniqueName(name, roster) {
  if (!roster.some((u) => u.name === name)) return name;
  const suffixes = ['', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX'];
  let i = 2;
  while (roster.some((u) => u.name === `${name} ${suffixes[i] || i}`)) i++;
  return `${name} ${suffixes[i] || i}`;
}

