// ── CHIMERA FRONT · deterministic-ish lane battle simulation ────────────────
import { NEXUS_HP, waveData } from './data.js';
import { makeEnemyUnit } from './units.js';

export const WORLD = { w: 1000, h: 620 };
export const LANE_X = [100, 300, 500, 700, 900];
export const START_Y = {
  player: { front: 424, back: 536 },
  enemy: { front: 220, back: 110 },
};
export const NEXUS_Y = { player: 604, enemy: 16 };
export const FIELD_MIN = 40;
export const FIELD_MAX = 580;
const ABILITY_AUTO_DELAY = { player: 6, enemy: 1.4 };

const rnd = (a, b) => a + Math.random() * (b - a);

function makeCombatUnit(unit, side, lane, row, idx) {
  const traits = new Set(unit.traits);
  const maxHp = unit.stats.hp;
  return {
    ref: unit,
    name: unit.name,
    side, lane, row,
    x: LANE_X[lane] + (row === 'front' ? -14 : 14) * (side === 'player' ? 1 : -1),
    y: START_Y[side][row] + ((idx % 3) - 1) * 2,
    maxHp,
    hp: maxHp,
    shield: traits.has('aegis') ? Math.round(maxHp * 0.25) : 0,
    atk: unit.stats.atk,
    interval: unit.stats.interval,
    range: unit.stats.range,
    speed: unit.stats.speed,
    traits,
    ability: unit.ability,
    tier: unit.tier,
    energy: 0,
    energyMax: 100,
    autoCastAt: 0,
    attackTimer: rnd(0.05, 0.5),
    status: { slow: 0, slowUntil: 0, stunUntil: 0, atkBuff: 0, atkBuffUntil: 0, haste: 0, hasteUntil: 0 },
    poison: [],
    burn: null,
    dotTimer: 0,
    flash: 0,
    lunge: 0,
    hitAnim: 0,
    alive: true,
    deathT: 0,
    atNexus: false,
    breakAnnounced: false,
    casts: 0,
    dmgDone: 0,
    healDone: 0,
  };
}

export function createBattle({ roster, slots, wave }) {
  const wd = waveData(wave);
  const battle = {
    time: 0,
    duration: 60,
    wave,
    waveData: wd,
    units: [],
    playerNexus: NEXUS_HP,
    enemyNexus: NEXUS_HP,
    events: [],
    over: false,
    winner: null,
    bloodrush: false,
    shake: 0,
    slots,
    roster,
    startedAt: performance.now ? performance.now() : 0,
  };

  let idx = 0;
  for (const [key, unitId] of Object.entries(slots || {})) {
    if (!unitId) continue;
    const ru = roster.find((u) => u.id === unitId);
    if (!ru) continue;
    const [laneS, row] = key.split('-');
    const lane = Number(laneS);
    if (lane < 0 || lane > 4) continue;
    battle.units.push(makeCombatUnit(ru, 'player', lane, row, idx++));
  }

  (wd.enemies || []).forEach((e, i) => {
    const ru = makeEnemyUnit(e, wave);
    battle.units.push(makeCombatUnit(ru, 'enemy', e.lane, e.row, 100 + i));
  });

  return battle;
}

function ev(b, type, data = {}) {
  b.events.push({ type, t: b.time, ...data });
}

export function drainEvents(b) {
  const out = b.events;
  b.events = [];
  return out;
}

const alive = (u) => u.alive && u.hp > 0;
const enemiesOf = (b, side) => b.units.filter((u) => alive(u) && u.side !== side);
const alliesOf = (b, side) => b.units.filter((u) => alive(u) && u.side === side);

function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

function sym(b, u) {
  return u.side === 'player' ? b.enemyNexus : b.playerNexus;
}
function hurtNexus(b, u, amount) {
  if (u.side === 'player') b.enemyNexus = Math.max(0, b.enemyNexus - amount);
  else b.playerNexus = Math.max(0, b.playerNexus - amount);
  u.dmgDone += amount;
  b.shake = Math.max(b.shake, Math.min(14, 4 + amount * 0.25));
  ev(b, 'nexus', {
    side: u.side === 'player' ? 'enemy' : 'player',
    from: u.side, lane: u.lane,
    x: LANE_X[u.lane], y: u.side === 'player' ? NEXUS_Y.enemy : NEXUS_Y.player,
    amount: Math.round(amount),
  });
  if (b.enemyNexus <= 0 && !b.over) finish(b, 'player');
  else if (b.playerNexus <= 0 && !b.over) finish(b, 'enemy');
}

  const reward = victory ? wd.reward : 0;
  const kills = S.battle.units.filter((u) => u.side === 'enemy' && !u.alive).length;
  const survivors = S.battle.units.filter((u) => u.side === 'player' && u.alive).length;
  const time = Math.min(60, Math.round(S.battle.time));
  if (victory) {
    S.essence += reward;
    S.best = Math.max(S.best, S.wave);
    localStorage.setItem('chimera-front-best', String(S.best));
  }
  updateNexusBars();
  updateOverlays();
  setTimeout(() => { if (S.screen === 'run') renderTitleBest(); }, 0);

  const newBest = victory && S.wave >= S.best;
  const isEndless = S.wave > WAVES.length;
  const resultStats = `
    <div class="rs"><small>WAVE</small><b>${isEndless ? '∞ ' + (S.wave - WAVES.length) : roman(S.wave)}</b></div>
    <div class="rs"><small>TIME</small><b>${time}s</b></div>
    <div class="rs"><small>BEASTS SLAIN</small><b>${kills}</b></div>
    <div class="rs"><small>SURVIVORS</small><b>${survivors}</b></div>
    <div class="rs"><small>SPLICES</small><b>${S.stats.splices}</b></div>
    <div class="rs"><small>NEXUS LEFT</small><b>${Math.ceil(S.battle.playerNexus)}</b></div>
  `;
  const actions = victory
    ? `<button class="btn btn-ghost" data-action="title">END RUN</button>
       <button class="btn btn-gold" data-action="next-wave">${S.wave >= 8 ? 'ENTER THE ENDLESS' : 'NEXT WAVE'} <span class="btn-arrow">›</span></button>`
    : `<button class="btn btn-ghost" data-action="title">RETURN TO TITLE</button>
       <button class="btn btn-primary" data-action="retry">TRY AGAIN <span class="btn-arrow">›</span></button>`;

  openModal(`
    <div class="modal result-modal ${victory ? 'win' : 'loss'}">
      <div class="modal-body">
        <div class="result-emblem"><span>${victory ? '◆' : '✕'}</span></div>
        <div class="result-kicker">${victory ? `WAVE ${isEndless ? 'ENDLESS' : roman(S.wave)} CLEARED` : 'THE RITE ENDS'}</div>
        <div class="result-title">${victory ? (S.wave === WAVES.length ? 'THE HOLLOW KING FALLS' : 'VICTORY') : 'DEFEAT'}</div>
        <p class="result-sub">${victory
          ? (S.wave >= WAVES.length ? 'The arena is silent. Its oldest hunger is finally fed.' : 'The enemy nexus shatters. Your chimeras taste blood and victory.')
          : `Your nexus broke on wave ${isEndless ? 'endless' : roman(S.wave)}. The rite begins again.`}</p>
        ${victory ? `<div class="result-reward"><span class="gem"></span>+${reward} ESSENCE ${newBest ? ' · NEW BEST WAVE' : ''}</div>` : ''}
        <div class="result-stats">${resultStats}</div>
        <div class="result-actions">${actions}</div>
      </div>
    </div>
    <div class="modal-backdrop" data-action="close-result" style="position:absolute"></div>
  `, true);
  // Put backdrop behind
  const root = els.modalRoot;
  const bd = root.querySelector('.modal-backdrop');
  const md = root.querySelector('.modal');
  if (bd && md) { root.insertBefore(bd, md); }
  updateBattleDock();
  hideOverlays();
}

function nextWave() {
  if (!S.battle) return;
  S.wave++;
  S.phase = 'prep';
  S.battle = null;
  S.battleLog = [];
  S.resultShown = false;
  S.speed = 1;
  S.selectedId = null;
  S.hover = null;
  S.chipEls = [];
  S.abilityUnits = [];
  S.shop = rollShop(S.wave);
