import { createBattle, stepBattle } from '/home/runner/work/PlayGround/PlayGround/src/battle.js'
import { makeBaseUnit, makeEnemyUnit, previewSplice, applySplice, spliceCost, combatPower } from '/home/runner/work/PlayGround/PlayGround/src/units.js'
import { WAVES, waveData, SPECIES } from '/home/runner/work/PlayGround/PlayGround/src/data.js'

function resetRoster() {
  return ['wolf', 'bear', 'falcon', 'serpent'].map(k => makeBaseUnit(k))
}

function deploy(roster, slots) {
  for (const k of Object.keys(slots)) delete slots[k]
  // assign each unit: melee to front, ranged to back; spread lanes, prioritize lanes with many enemies
  const laneOrder = [2, 1, 3, 0, 4]
  const used = { front: [0, 0, 0, 0, 0], back: [0, 0, 0, 0, 0] }
  const sorted = [...roster].sort((a, b) => combatPower(b) - combatPower(a))
  for (const u of sorted) {
    const row = u.stats.range >= 150 ? 'back' : 'front'
    let lane = laneOrder.find(l => used[row][l] === 0)
    if (lane == null) lane = laneOrder.find(l => used[row][l] < 2)
    if (lane == null) continue
    used[row][lane]++
    u.lane = lane; u.row = row
    slots[`${lane}-${row}`] = u.id
  }
  return slots
}

function simulate(roster, slots, wave) {
  const b = createBattle({ roster, slots, wave })
  let guard = 0
  while (!b.over && guard++ < 60 * 70) stepBattle(b, 1 / 60)
  return { win: b.winner === 'player', time: b.time, px: b.playerNexus, ex: b.enemyNexus }
}

function run(strategy) {
  let roster = resetRoster()
  let essence = 14
  let splices = 0
  const slots = {}
  const log = []
  for (let wave = 1; wave <= 12; wave++) {
    deploy(roster, slots)
    const r = simulate(roster, slots, wave)
    log.push(`W${wave} ${r.win ? 'WIN ' : 'LOSS'} t=${r.time.toFixed(0)} nexus=${r.px.toFixed(0)} foes=${waveData(wave).enemies.length} roster=${roster.length} pow=${roster.reduce((s, u) => s + combatPower(u), 0)}`)
    if (!r.win) return { log, cleared: wave - 1, roster, essence, splices }
    essence += waveData(wave).reward
    // post-wave economy
    if (strategy === 'smart') {
      // splice if roster full or we can afford and have 2 units, prefer strongest as primary
      let did = false
      while (roster.length >= 7 && roster.length >= 2) {
        const pairs = []
        for (let i = 0; i < roster.length; i++) for (let j = i + 1; j < roster.length; j++) {
          const c = spliceCost(roster[i], roster[j])
          if (c <= essence) pairs.push({ i, j, c, pow: combatPower(previewSplice(roster[i], roster[j])) })
        }
        if (!pairs.length) break
        pairs.sort((a, b) => b.pow - a.pow)
        const p = pairs[0]
        const res = applySplice(roster, roster[p.i].id, roster[p.j].id)
        roster = res.roster; essence -= p.c; splices++; did = true
        if (splices > 12) break
      }
      // recruit
      let guard = 0
      while (roster.length < 8 && guard++ < 5) {
        const cost = 5 + Math.ceil(wave / 2)
        if (essence < cost) break
        const keys = Object.keys(SPECIES)
        const k = keys[(wave * 7 + guard * 3) % keys.length]
        roster.push(makeBaseUnit(k)); essence -= cost
      }
      // if rich, splice more
      while (essence > 12 && roster.length >= 4 && splices < 14) {
        const pairs = []
        for (let i = 0; i < roster.length; i++) for (let j = i + 1; j < roster.length; j++) {
          const c = spliceCost(roster[i], roster[j])
          if (c <= essence) pairs.push({ i, j, c, pow: combatPower(previewSplice(roster[i], roster[j])) })
        }
        if (!pairs.length) break
        pairs.sort((a, b) => b.pow - a.pow)
        const p = pairs[0]
        const res = applySplice(roster, roster[p.i].id, roster[p.j].id)
        roster = res.roster; essence -= p.c; splices++
      }
    }
  }
  return { log, cleared: 12, roster, essence, splices }
}

for (const strat of ['naive', 'smart']) {
  const r = run(strat)
  console.log(`\n=== ${strat.toUpperCase()} cleared ${r.cleared} ===`)
  console.log(r.log.join('\n'))
  console.log('final roster', r.roster.map(u => `${u.name} T${u.tier} ${u.stats.range >= 150 ? 'R' : 'M'}`).join(', '), 'essence', r.essence, 'splices', r.splices)
}

