import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
page.setDefaultTimeout(15000)
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.waitForTimeout(500)
const shot = async (name) => { await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 85 }) }
await page.click('#startBtn')
await page.waitForTimeout(500)
// click first roster card, then click world slot (lane 2 front)
await page.locator('#dockBody .unit-card').first().click()
await page.waitForTimeout(300)
console.log('SELECTED', await page.evaluate(() => window.__CHIMERA.S.selectedId))
// compute client coords for world (360, 328) using view
const pt = await page.evaluate(() => {
  const av = window.__CHIMERA.arena
  const rect = av.canvas.getBoundingClientRect()
  const { scale, ox, oy } = av.view
  const wx = 360, wy = 328
  return { x: rect.left + ox + wx * scale, y: rect.top + oy + wy * scale }
})
console.log('CLICK AT', pt)
await page.mouse.click(pt.x, pt.y)
await page.waitForTimeout(500)
console.log('SLOTS', await page.evaluate(() => ({ slots: window.__CHIMERA.S.slots, sel: window.__CHIMERA.S.selectedId, roster: window.__CHIMERA.S.roster.map(u => [u.name, u.lane, u.row]) })))
await shot('click-deploy')
console.log('ERRORS', errors.length)
await browser.close()

