}

function deployUnit(id, key) {
  const unit = S.roster.find((u) => u.id === id);
  if (!unit) return;
  let fromKey = null;
  for (const [k, v] of Object.entries(S.slots)) if (v === id) { fromKey = k; break; }
  const occupant = S.slots[key];
  if (fromKey === key) return;
  if (occupant && occupant !== id) {
