import { createBattle, stepBattle } from '/home/runner/work/PlayGround/PlayGround/src/battle.js'
import { makeBaseUnit, makeEnemyUnit, previewSplice, applySplice, spliceCost, combatPower } from '/home/runner/work/PlayGround/PlayGround/src/units.js'
import { WAVES, waveData, SPECIES, STARTING_ROSTER } from '/home/runner/work/PlayGround/PlayGround/src/data.js'

const rarity = (k) => SPECIES[k]

function deploy(roster, slots, wave) {
  for (const k of Object.keys(slots)) delete slots[k]
  const wd = waveData(wave)
  const enemies = wd.enemies || []
  const laneFoes = [0, 0, 0, 0, 0]
  for (const e of enemies) laneFoes[e.lane]++
  const ally = { front: [0, 0, 0, 0, 0], back: [0, 0, 0, 0, 0] }
  const sorted = [...roster].sort((a, b) => combatPower(b) - combatPower(a))
  for (const u of sorted) {
    const row = u.stats.range >= 150 ? 'back' : 'front'
    let best = -1, bs = -1e9
    for (let l = 0; l < 5; l++) {
      const s = laneFoes[l] * 10 - (ally.front[l] + ally.back[l]) * 6 - ally[row][l] * 5 + (row === 'front' ? (l === 2 ? 0.5 : 0) : 0)
      if (s > bs) { bs = s; best = l }
    }
    ally[row][best]++
    u.lane = best; u.row = row
    slots[`${best}-${row}`] = u.id
  }
  return slots
}

function simulate(roster, slots, wave) {
  const b = createBattle({ roster, slots, wave })
  let guard = 0
  while (!b.over && guard++ < 60 * 70) stepBattle(b, 1 / 60)
  return { win: b.winner === 'player', time: b.time, px: b.playerNexus, ex: b.enemyNexus, survivors: b.units.filter(u => u.side === 'player' && u.alive).length }
}

function buyAndSplice(roster, essence, wave, splices, policy) {
  // 1) buy available recruits if space
  let guard = 0
  while (roster.length < (policy.maxRoster || 8) && guard++ < 6) {
    const cost = 5 + Math.ceil(wave / 2)
    if (essence < cost) break
    // choose deterministic "best" species from pool rotation
    const pool = ['golem', 'drake', 'wraith', 'bear', 'rhino', 'serpent', 'toad', 'falcon', 'wolf', 'lynx', 'scorpion', 'mantis']
    const k = pool[(wave * 5 + guard * 7) % pool.length]
    roster.push(makeBaseUnit(k)); essence -= cost
  }
  // 2) splice: choose pair with best power gain per essence, only if above threshold
  let iterations = 0
  while (roster.length >= 2 && iterations++ < 10) {
    let best = null
