        for(let i=0;i<roster.length;i++)for(let j=i+1;j<roster.length;j++){
          const c=spliceCost(roster[i],roster[j]); if(c>essence)continue
          const hy=previewSplice(roster[i],roster[j]); const gain=combatPower(hy)-Math.max(combatPower(roster[i]),combatPower(roster[j]))
          if(!best||gain>best.gain)best={i,j,c,gain}
        }
        if(best){const r=applySplice(roster,roster[best.i].id,roster[best.j].id);roster=r.roster;essence-=best.c;splices++;acted=true}
      }
      if(!acted)break
    }
  }
  return {cleared:Math.min(wave-1,12),log,roster}
}
