import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const errors = []
async function run(name, width, height) {
  const page = await browser.newPage({ viewport: { width, height } })
  page.setDefaultTimeout(15000)
  page.on('pageerror', e => { errors.push(name + ': ' + e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errors.push(name + ': ' + m.text()); console.log('CONSOLE', m.text()) } })
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  await page.waitForTimeout(600)
  await page.screenshot({ path: `screenshots/${name}-title.jpg`, type: 'jpeg', quality: 82 })
  await page.click('#startBtn')
  await page.waitForTimeout(700)
  await page.screenshot({ path: `screenshots/${name}-prep.jpg`, type: 'jpeg', quality: 82 })
  // deploy + battle
  await page.evaluate(() => {
    const S = window.__CHIMERA.S
    const lanes = [[0, 'front'], [1, 'front'], [2, 'front'], [3, 'back']]
    S.roster.forEach((u, i) => { const [l, r] = lanes[i]; u.lane = l; u.row = r; S.slots[`${l}-${r}`] = u.id })
    window.__CHIMERA.renderAll()
  })
  await page.waitForTimeout(300)
  await page.screenshot({ path: `screenshots/${name}-prep2.jpg`, type: 'jpeg', quality: 82 })
  await page.evaluate(() => window.__CHIMERA.startBattle())
  await page.evaluate(() => window.__CHIMERA.fastForward(4))
  await page.waitForTimeout(300)
  await page.screenshot({ path: `screenshots/${name}-battle.jpg`, type: 'jpeg', quality: 82 })
  // help modal
  await page.evaluate(() => window.__CHIMERA.fastForward(30))
  await page.waitForTimeout(300)
  const nxt = await page.$('[data-action="next-wave"]')
  if (nxt) { await nxt.click(); await page.waitForTimeout(800) }
  await page.screenshot({ path: `screenshots/${name}-wave2.jpg`, type: 'jpeg', quality: 82 })
  const help = await page.$('[data-action="help"], #helpBtn')
  console.log(name, 'help btn', !!help)
  await page.close()
}
await run('desk', 1280, 800)
await run('mob', 390, 844)
console.log('ERRORS', errors.length, errors.slice(0, 8))
await browser.close()

